INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C1','math',2,2,'u2',2,'2단 곱셈구구 — 한 묶음이 2씩 늘어나는 상황을 곱셈식으로 나타내고, 2 × 5를 2씩 5번 더하기와 2 × 4에 2 더하기로 구하며, 곱하는 수가 1 커지면 곱이 2씩 커짐을 알기',ARRAY['2수01-11']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C2','math',2,2,'u2',3,'5단 곱셈구구 — 5씩 커지는 원리로 5단을 완성하고, 곱의 일의 자리 숫자가 5, 0으로 되풀이되는 규칙을 찾기',ARRAY['2수01-11']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C3','math',2,2,'u2',4,'3단·6단 곱셈구구 — 3씩·6씩 커지는 원리로 3단과 6단을 완성하고, 6 × 5를 5 × 6처럼 다르게 묶어 구하며, 6단의 곱이 3단의 곱의 2배임을 알기',ARRAY['2수01-11']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C4','math',2,2,'u2',5,'4단·8단 곱셈구구 — 4씩·8씩 커지는 원리로 4단과 8단을 완성하고, 8 × 6을 8 × 3 두 번 더하기 등 여러 방법으로 구하며, 8단의 곱이 4단의 곱의 2배임을 알기',ARRAY['2수01-11']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C5','math',2,2,'u2',6,'7단 곱셈구구 — 수직선에서 7씩 뛰어 세고, 7 × 5를 7 × 3과 7 × 2로 나누어 구하며, 7 × 6을 7 × 5에 7 더하기와 6 × 7로 구해 7단을 완성하기',ARRAY['2수01-11']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C6','math',2,2,'u2',7,'9단 곱셈구구 — 9씩 커지는 원리로 9단을 완성하고, 9 × 5를 9 × 2와 9 × 3의 곱을 더해 구하며, 곱의 두 숫자의 합이 9인 규칙을 찾기',ARRAY['2수01-11']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C7','math',2,2,'u2',8,'1단 곱셈구구와 0의 곱 — 1과 어떤 수의 곱은 그 수, 0과 어떤 수의 곱과 어떤 수와 0의 곱은 0임을 알고 점수 상황에 쓰기',ARRAY['2수01-11']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C8','math',2,2,'u2',9,'곱셈표 — 가로줄과 세로줄의 수가 만나는 칸에 곱을 써서 곱셈표를 만들고, 단마다 곱이 그 단의 수만큼 커지는 원리로 빈칸을 채우며, 두 수를 바꾸어 곱해도 곱이 같고 곱이 같은 곱셈구구가 여럿일 수 있음을 알기',ARRAY['2수01-11']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C9','math',2,2,'u2',10,'곱셈구구로 문제 해결하기 — 생활 속 물건의 수를 곱셈구구로 구하고, 빈자리가 있거나 두 덩이로 된 배열은 나누어 곱한 뒤 더하거나 빼서 구하기',ARRAY['2수01-11']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C10','math',2,2,'u2',12,'곱셈구구 속 규칙 찾기 — 곱의 일의 자리 숫자를 차례로 이어 단마다 생기는 무늬를 찾고, 다른 단인데 같은 무늬가 나오는 까닭을 말하기',ARRAY['2수01-11']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X01','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6']::text[],'곱하는 수가 1 커지면 곱도 1 커진다고 여긴다(2 × 5를 2 × 4보다 1 크다고 봄)','곱하는 수가 1 커지면 그 단의 수를 한 번 더 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X02','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C8']::text[],'곱셈구구의 곱을 이웃 곱(한 번 더·덜 뛴 값)과 헷갈리거나 뛰어 세기를 한 번 더·덜 한다','뛸 때마다 손가락을 하나씩 접어 곱하는 수만큼 뛰었는지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X03','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'그림에서 묶음이나 줄의 수를 하나 더·덜 센다','묶음·줄마다 번호를 붙이며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X04','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'「몇씩」(한 묶음·한 줄의 수)과 「몇 묶음·몇 줄」을 뒤바꾸어 곱셈식을 쓴다','× 앞에는 한 묶음의 수, 뒤에는 묶음의 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X05','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C7','M2-2-u2-C9']::text[],'묻는 것 대신 곱하는 수·묶음 수·맞힌 횟수 같은 다른 수를 답으로 쓴다','물음이 「모두 몇」인지 「몇 번·몇 묶음」인지 밑줄 긋기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X06','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C7','M2-2-u2-C9']::text[],'곱셈구구를 두 수를 더하거나 빼서 구한다(2 × 5 = 7)','두 수를 더하지 말고 앞의 수를 뒤의 수만큼 여러 번 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X07','math',2,'u2',ARRAY['M2-2-u2-C1']::text[],'「몇의 몇 배」를 곱셈식으로 옮길 때 두 수를 뒤바꾼다','「몇의」 수가 × 앞, 「몇 배」 수가 × 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X08','math',2,'u2',ARRAY['M2-2-u2-C7']::text[],'0이나 1을 곱할 때 0의 곱을 그 수로(3 × 0 = 3), 1의 곱을 1로(1 × 5 = 1) 여기거나, 한 번도 못 맞힌 점수를 그 점수로 센다','0번 더하면 아무것도 없어 0, 1을 몇 번 더하면 그 횟수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X09','math',2,'u2',ARRAY['M2-2-u2-C8']::text[],'곱셈표에서 가로줄·세로줄을 잘못 짚어 이웃 칸을 읽거나 줄과 칸을 뒤바꾼다','왼쪽 수와 위쪽 수를 손가락 두 개로 짚어 만나는 칸 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X10','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C4']::text[],'단과 단 사이의 관계를 모른다 — 6단을 3단과, 8단을 4단과 따로 외우거나, 같은 수를 곱할 때 6단의 곱이 3단의 곱의 2배임을 모른다','3씩 2묶음이 6, 4씩 2묶음이 8 — 묶음을 두 개씩 합쳐 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X11','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'× 를 + 로 여기거나 곱셈식을 잘못 읽는다','× 는 「곱하기」 — 앞의 수를 뒤의 수만큼 여러 번 더한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X12','math',2,'u2',ARRAY['M2-2-u2-C1']::text[],'같은 수의 덧셈을 곱셈식으로 바꿀 때 더한 횟수를 잘못 센다','더하기 기호가 아니라 더한 수가 몇 번 나오는지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X13','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C5','M2-2-u2-C7','M2-2-u2-C8']::text[],'두 수를 바꾸어 곱해도 곱이 같다는 것을 모르거나, 곱이 같은 곱셈구구를 하나만 찾는다(24 = 3 × 8 = 4 × 6을 놓침)','곱셈표를 점선을 따라 접어 만나는 칸, 같은 곱이 나오는 다른 단 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X14','math',2,'u2',ARRAY['M2-2-u2-C9']::text[],'생활 속 상황에서 한 묶음의 수와 묶음의 수를 잘못 잡는다(다리 수와 마리 수를 헷갈림)','「한 ○에 몇 개씩」이 한 묶음, 「○가 몇」이 묶음 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X15','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C7','M2-2-u2-C8','M2-2-u2-C9','M2-2-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못된↔바른','물음의 「아닌·잘못된」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X16','math',2,'u2',ARRAY['M2-2-u2-C2','M2-2-u2-C6','M2-2-u2-C8','M2-2-u2-C10']::text[],'곱의 규칙(5단 일의 자리 5·0, 9단 두 숫자의 합 9, 일의 자리 무늬)을 곱하는 수의 규칙과 헷갈리거나 곱 전체를 이어 잘못 찾는다','곱을 차례로 쓰고 일의 자리·십의 자리 숫자에 따로 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X17','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C9']::text[],'한 번 더 더하기·나누어 구하기에서 곱하는 수를 더하거나(2 × 4 + 5) 두 곱 대신 두 수만 더한다(9 × 2와 9 × 3에서 2 + 3)','한 번 더 더할 때는 그 단의 수를, 나누어 구할 때는 두 곱을 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X18','math',2,'u2',ARRAY['M2-2-u2-C9']::text[],'줄 맞춰 놓이지 않은 배열(빈자리·두 덩이·낱개)에서 빈자리를 빼지 않거나 한 덩이·낱개를 빠뜨린다','빈자리에 ×, 덩이마다 색을 다르게 칠하고 따로 구하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X19','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C8','M2-2-u2-C9']::text[],'곱을 구하지 않고 앞의 수나 한 수만 보고 두 곱셈식의 크기를 견준다','두 곱셈식의 곱을 먼저 구해 옆에 쓰고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X20','math',2,'u2',ARRAY['M2-2-u2-C8']::text[],'여러 조건이 있는 「어떤 수」 문제에서 조건 하나를 빠뜨리고, 일부 조건만 맞는 수를 고른다(7단·짝수·27보다 크고 36보다 작은 수에서 14나 35를 고름)','조건마다 번호를 붙이고, 고른 수가 조건을 하나씩 모두 지키는지 ✔ 표시하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X21','math',2,'u2',ARRAY['M2-2-u2-C9']::text[],'물건을 하나씩 세는 것은 틀린 방법이라고 여기거나, 곱셈구구로 구하지 않으면 답이 틀린다고 생각한다','하나씩 세어도 답은 같아요 — 곱셈구구는 같은 답을 더 빠르고 편리하게 구하는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#1','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'mc','auto','미래 교육 체험관의 스마트 팜에서 딸기를 4개씩 3묶음 땄어요. 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"mc","stem":"미래 교육 체험관의 스마트 팜에서 딸기를 4개씩 3묶음 땄어요. 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × 3 = 12","correct":true},{"t":"4 + 3 = 7","mis":"M2-2-u2-X11"},{"t":"4 × 4 = 16","mis":"M2-2-u2-X03"}],"explanation":["4씩 3묶음은 4의 3배예요.","4 + 4 + 4 = 12이니 곱셈식으로 4 × 3 = 12예요.","× 앞에는 한 묶음의 수 4, 뒤에는 묶음의 수 3을 써요."],"asset":{"type":"mul_groups","item":"🍓","k":4,"n":3},"variant_rule":{"alt":[{"stem":"4의 3배를 덧셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 + 4 + 4 = 12","correct":true},{"t":"4 + 3 = 7","mis":"M2-2-u2-X11"},{"t":"4 + 4 = 8","mis":"M2-2-u2-X12"}],"explanation":["4의 3배는 4를 3번 더한 것이에요.","4 + 4 + 4 = 12예요.","더한 4가 몇 개인지 세면 3개 — 4 × 3과 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#2','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'sa','auto','로봇 바퀴가 2개씩 들어 있는 봉지가 4봉지 있어요. 바퀴는 모두 몇 개인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"로봇 바퀴가 2개씩 들어 있는 봉지가 4봉지 있어요. 바퀴는 모두 몇 개인가요?","answer":["8","8개"],"explanation":["한 봉지에 2개씩, 4봉지예요.","2씩 4번 뛰어 세면 2, 4, 6, 8이에요.","2 × 4 = 8 — 바퀴는 모두 8개예요."],"asset":{"type":"mul_groups","item":"⚫","k":2,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#3','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'mc','auto','로봇 한 대에 바퀴가 2개씩 있어요. 로봇 3대를 만드는 데 필요한 바퀴는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":3,"concept":"M2-2-u2-C1","difficulty":1,"kind":"mc","stem":"로봇 한 대에 바퀴가 2개씩 있어요. 로봇 3대를 만드는 데 필요한 바퀴는 모두 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"5개","mis":"M2-2-u2-X06"},{"t":"8개","mis":"M2-2-u2-X02"}],"explanation":["로봇 한 대에 바퀴 2개 — 2씩 3묶음이에요.","2씩 3묶음은 2의 3배, 2 × 3 = 6이에요.","2와 3을 더하면 안 돼요 — 2를 3번 더해요."],"asset":{"type":"mul_groups","item":"⚫","k":2,"n":3},"variant_rule":{"alt":[{"stem":"로봇 한 대에 바퀴가 2개씩 있어요. 로봇 5대를 만드는 데 필요한 바퀴는 모두 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"7개","mis":"M2-2-u2-X06"},{"t":"12개","mis":"M2-2-u2-X02"}],"explanation":["2씩 5묶음이에요.","2 + 2 + 2 + 2 + 2 = 10, 2 × 5 = 10이에요.","그래서 바퀴는 10개 있어야 해요."],"asset":{"type":"mul_groups","item":"⚫","k":2,"n":5}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#4','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'blank','auto','2 × 4는 2 × 3보다 (        )만큼 더 커요.',ARRAY['M2-2-u2-X01','M2-2-u2-X05']::text[],false,'{"seq":4,"concept":"M2-2-u2-C1","difficulty":1,"kind":"blank","stem":"2 × 4는 2 × 3보다 (        )만큼 더 커요.","options":[{"t":"2","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X05"}],"explanation":["2 × 3은 2씩 3묶음, 2 × 4는 2씩 4묶음이에요.","2씩 1묶음이 더 많으니 2만큼 더 커요.","그래서 「2 × 4는 2 × 3보다 2만큼 더 큽니다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#5','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'mc','auto','2 × 5를 계산하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X06']::text[],true,'{"seq":5,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"2 × 5를 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 4 = 8에 2를 더해요.","correct":true},{"t":"2 × 4 = 8에 5를 더해요.","mis":"M2-2-u2-X17"},{"t":"2와 5를 더해요.","mis":"M2-2-u2-X06"}],"explanation":["2 × 5는 2 × 4보다 2씩 1묶음이 더 많아요.","그래서 2 × 4 = 8에 2를 더하면 10이에요.","5를 더하거나 2와 5를 더하면 안 돼요."],"variant_rule":{"alt":[{"stem":"2 × 5를 같은 수를 여러 번 더해서 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"2를 5번 더해요.","correct":true},{"t":"2를 4번 더해요.","mis":"M2-2-u2-X12"},{"t":"2와 5를 한 번씩 더해요.","mis":"M2-2-u2-X06"}],"explanation":["2 × 5는 2씩 5번 더한 것이에요.","2 + 2 + 2 + 2 + 2 = 10이에요.","더하는 2가 5개인지 꼭 세어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#6','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'sa','auto','2 + 2 + 2 + 2 + 2 = 2 × □ 에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":6,"concept":"M2-2-u2-C1","difficulty":2,"kind":"sa","stem":"2 + 2 + 2 + 2 + 2 = 2 × □ 에서 □ 안에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["더한 수 2가 몇 개인지 세어요.","2가 5개예요.","그래서 2 + 2 + 2 + 2 + 2 = 2 × 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#7','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'match','auto','로봇 6대, 7대, 8대의 바퀴 수를 곱셈식으로 나타냈어요. 곱셈식과 곱을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M2-2-u2-C1","difficulty":2,"kind":"match","stem":"로봇 6대, 7대, 8대의 바퀴 수를 곱셈식으로 나타냈어요. 곱셈식과 곱을 이어 보세요.","pairs":[{"l":"2 × 6","r":"12"},{"l":"2 × 7","r":"14"},{"l":"2 × 8","r":"16"}],"mis":"M2-2-u2-X02","explanation":["2 × 6은 2씩 6번 — 12예요.","2 × 7은 2 × 6보다 2 커서 14, 2 × 8은 16이에요.","로봇이 한 대 늘 때마다 바퀴는 2개씩 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#8','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'ox','auto','2단 곱셈구구에서 곱하는 수가 1씩 커지면 곱은 2씩 커져요.',ARRAY['M2-2-u2-X01']::text[],false,'{"seq":8,"concept":"M2-2-u2-C1","difficulty":2,"kind":"ox","stem":"2단 곱셈구구에서 곱하는 수가 1씩 커지면 곱은 2씩 커져요.","answer":"O","reason_options":[{"t":"로봇이 한 대 늘 때마다 바퀴가 2개씩 더 생기니까","correct":true},{"t":"곱하는 수가 1 커지면 곱도 1 커지니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["2 × 1 = 2, 2 × 2 = 4, 2 × 3 = 6 …","곱하는 수가 1 커질 때마다 2를 한 번 더 더해요.","그래서 곱은 2씩 커져요 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#9','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'mc','auto','체험 안경 1개를 만들려면 ○ 모양이 2개 필요해요. 체험 안경 7개를 만들려면 ○ 모양은 모두 몇 개 필요한가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"체험 안경 1개를 만들려면 ○ 모양이 2개 필요해요. 체험 안경 7개를 만들려면 ○ 모양은 모두 몇 개 필요한가요?","options":[{"t":"14개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"12개","mis":"M2-2-u2-X02"}],"explanation":["안경 1개에 ○ 2개 — 2씩 7묶음이에요.","2단 곱셈구구로 2 × 7 = 14예요.","그래서 ○ 모양은 모두 14개 필요해요."],"variant_rule":{"alt":[{"stem":"체험 안경 1개를 만들려면 ○ 모양이 2개 필요해요. 체험 안경 9개를 만들려면 ○ 모양은 모두 몇 개 필요한가요?","options":[{"t":"18개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"16개","mis":"M2-2-u2-X02"}],"explanation":["2씩 9묶음이에요.","2 × 9 = 18이에요.","그래서 ○ 모양은 18개 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_basic#10','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',3,'mc','auto','로봇 8대에 바퀴가 16개 필요해요. 로봇 9대를 만들려면 바퀴는 모두 몇 개 필요한가요? (로봇 한 대에 바퀴 2개)',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],false,'{"seq":10,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"로봇 8대에 바퀴가 16개 필요해요. 로봇 9대를 만들려면 바퀴는 모두 몇 개 필요한가요? (로봇 한 대에 바퀴 2개)","options":[{"t":"18개","correct":true},{"t":"17개","mis":"M2-2-u2-X01"},{"t":"25개","mis":"M2-2-u2-X17"}],"explanation":["로봇이 한 대 늘면 바퀴가 2개 더 필요해요.","2 × 9는 2 × 8 = 16보다 2 커서 18이에요.","16에 1이나 9를 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#1','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',2,'mc','auto','체험관 그림에 야구공이 9개씩 5묶음 있어요. 하나씩 세지 않고 곱셈식으로 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],false,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"체험관 그림에 야구공이 9개씩 5묶음 있어요. 하나씩 세지 않고 곱셈식으로 나타낸 것은 어느 것인가요?","options":[{"t":"9 × 5","correct":true},{"t":"9 + 5","mis":"M2-2-u2-X11"},{"t":"9 × 4","mis":"M2-2-u2-X03"}],"explanation":["한 묶음에 9개씩 — × 앞에 9를 써요.","5묶음이니 × 뒤에 5를 써요.","9씩 5묶음 = 9의 5배 = 9 × 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#2','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',2,'error','auto','2 × 4가 2 × 3보다 얼마나 더 큰지 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X15']::text[],false,'{"seq":2,"concept":"M2-2-u2-C1","difficulty":2,"kind":"error","stem":"2 × 4가 2 × 3보다 얼마나 더 큰지 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 1묶음이 더 많으니까 1만큼 더 커.","correct":true,"mis_target":"M2-2-u2-X01"},{"t":"준우: 2의 4배는 2의 3배보다 2만큼 더 커.","mis":"M2-2-u2-X15"},{"t":"라희: 6에서 8로 2만큼 커졌어.","mis":"M2-2-u2-X15"}],"explanation":["2 × 3 = 6, 2 × 4 = 8이에요.","묶음이 1개 더 많지만 한 묶음이 2개라 2만큼 커요.","그래서 서아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#3','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','곱셈식 6 × 3 = 18로 나타낼 수 있는 장면은 어느 것인가요?',ARRAY['M2-2-u2-X04','M2-2-u2-X11']::text[],false,'{"seq":3,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"곱셈식 6 × 3 = 18로 나타낼 수 있는 장면은 어느 것인가요?","options":[{"t":"딸기가 한 쟁반에 6개씩 3쟁반 있어요.","correct":true},{"t":"딸기가 한 쟁반에 3개씩 6쟁반 있어요.","mis":"M2-2-u2-X04"},{"t":"딸기가 6개와 3개 있어요.","mis":"M2-2-u2-X11"}],"explanation":["6 × 3은 6씩 3묶음, 6의 3배예요.","한 쟁반에 6개씩, 쟁반이 3개인 장면이에요.","3개씩 6쟁반은 3 × 6으로 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#4','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'sa','auto','2씩 7묶음을 2씩 5묶음과 2씩 몇 묶음으로 나누어 생각할 수 있나요?','{}'::text[],false,'{"seq":4,"concept":"M2-2-u2-C1","difficulty":3,"kind":"sa","stem":"2씩 7묶음을 2씩 5묶음과 2씩 몇 묶음으로 나누어 생각할 수 있나요?","answer":["2","2묶음"],"explanation":["7묶음 = 5묶음 + 2묶음이에요.","2씩 5묶음은 10, 2씩 2묶음은 4예요.","10과 4를 모으면 14 — 2 × 7 = 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#5','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','체험 안경 1개를 만들려면 ○ 모양이 2개 필요해요. ○ 모양이 18개 있으면 체험 안경을 몇 개 만들 수 있나요?',ARRAY['M2-2-u2-X02','M2-2-u2-X05']::text[],false,'{"seq":5,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"체험 안경 1개를 만들려면 ○ 모양이 2개 필요해요. ○ 모양이 18개 있으면 체험 안경을 몇 개 만들 수 있나요?","options":[{"t":"9개","correct":true},{"t":"8개","mis":"M2-2-u2-X02"},{"t":"16개","mis":"M2-2-u2-X05"}],"explanation":["2단 곱셈구구에서 곱이 18인 것을 찾아요.","2 × 9 = 18이에요.","그래서 체험 안경을 9개 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#6','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','로봇이 한 대씩 늘어날 때 바퀴의 수를 차례로 썼어요. 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":6,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"로봇이 한 대씩 늘어날 때 바퀴의 수를 차례로 썼어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"14","correct":true},{"t":"13","mis":"M2-2-u2-X01"},{"t":"18","mis":"M2-2-u2-X02"}],"explanation":["바퀴는 로봇이 한 대 늘 때마다 2개씩 많아져요.","12 다음은 12 + 2 = 14예요.","14 다음에 2를 더하면 16이 맞아요."],"asset":{"type":"jump_row","cells":[8,10,12,null,16],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#7','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'ox','auto','2 × 6은 2 × 3을 두 번 더한 것과 같아요.',ARRAY['M2-2-u2-X17']::text[],false,'{"seq":7,"concept":"M2-2-u2-C1","difficulty":3,"kind":"ox","stem":"2 × 6은 2 × 3을 두 번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"2씩 6묶음은 2씩 3묶음이 두 개라 6 + 6 = 12니까","correct":true},{"t":"2 × 3에 3을 더하면 2 × 6이 되니까","mis":"M2-2-u2-X17"}],"mis":"M2-2-u2-X17","explanation":["2 × 3 = 6이에요.","2씩 6묶음은 2씩 3묶음 두 개 — 6 + 6 = 12예요.","2 × 6 = 12이니 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#8','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'essay','teacher','2 × 5를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C1","difficulty":4,"kind":"essay","stem":"2 × 5를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예) 2씩 5번 더하면 2 + 2 + 2 + 2 + 2 = 10이다. 2 × 4 = 8에 2를 한 번 더 더하면 10이다. 그래서 2 × 5 = 10이다.","scoring_points":["같은 수를 여러 번 더하는 방법(동수누가)으로 10을 구했는가","2 × 4에 2를 더하는 방법(한 번 더 더하기)으로 10을 구했는가","2 × 5 = 10이라고 썼는가"]},"explanation":["2 × 5는 2를 5번 더한 것이에요.","2 × 4보다 2씩 1묶음이 더 많아요.","두 방법 모두 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#9','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'mc','auto','로봇 3대를 만든 뒤 로봇 4대를 더 만들었어요. 로봇 한 대에 바퀴가 2개씩이면 바퀴는 모두 몇 개 필요한가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X18']::text[],false,'{"seq":9,"concept":"M2-2-u2-C1","difficulty":4,"kind":"mc","stem":"로봇 3대를 만든 뒤 로봇 4대를 더 만들었어요. 로봇 한 대에 바퀴가 2개씩이면 바퀴는 모두 몇 개 필요한가요?","options":[{"t":"14개","correct":true},{"t":"7개","mis":"M2-2-u2-X05"},{"t":"8개","mis":"M2-2-u2-X18"}],"explanation":["로봇은 모두 3 + 4 = 7대예요.","2 × 7 = 14 — 6개와 8개를 더해도 14개예요.","로봇 수 7을 답으로 쓰거나 한쪽만 세면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L02_challenge#10','math',2,2,'u2','L02','tb_g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'essay','teacher','미래 교육 체험관에서 곱셈으로 나타낼 수 있는 장면을 하나 골라 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 나타내 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C1","difficulty":4,"kind":"essay","stem":"미래 교육 체험관에서 곱셈으로 나타낼 수 있는 장면을 하나 골라 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 나타내 보세요.","answer_guide":{"answer":"예) 로봇 한 대에 바퀴가 2개씩이고 로봇이 4대 있다 — 2씩 4묶음, 2의 4배, 2 × 4 = 8.","scoring_points":["같은 수씩 여러 묶음인 장면을 골랐는가","몇씩 몇 묶음과 몇의 몇 배로 바르게 나타냈는가","곱셈식과 곱을 바르게 썼는가"]},"explanation":["같은 수씩 묶여 있거나 줄 맞춰 놓인 물건을 찾아요.","한 묶음의 수와 묶음의 수를 찾아요.","한 묶음의 수 × 묶음의 수로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#1','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'mc','auto','쟁반 한 개에 딸기가 5개씩 담겨 있어요. 쟁반 3개에 담긴 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":1,"concept":"M2-2-u2-C2","difficulty":1,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩 담겨 있어요. 쟁반 3개에 담긴 딸기는 모두 몇 개인가요?","options":[{"t":"15개","correct":true},{"t":"8개","mis":"M2-2-u2-X06"},{"t":"20개","mis":"M2-2-u2-X02"}],"explanation":["쟁반 한 개에 5개씩, 쟁반 3개 — 5씩 3묶음이에요.","5, 10, 15로 뛰어 세면 15예요.","5 × 3 = 15 — 딸기는 15개예요."],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":3},"variant_rule":{"alt":[{"stem":"쟁반 한 개에 딸기가 5개씩 담겨 있어요. 쟁반 4개에 담긴 딸기는 모두 몇 개인가요?","options":[{"t":"20개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"25개","mis":"M2-2-u2-X02"}],"explanation":["5씩 4묶음이에요.","5, 10, 15, 20으로 뛰어 세요.","5 × 4 = 20 — 딸기는 20개예요."],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":4}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#2','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'blank','auto','○를 그려 보면 5 × 4는 5 × 3보다 (        )만큼 더 커요.',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],false,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"blank","stem":"○를 그려 보면 5 × 4는 5 × 3보다 (        )만큼 더 커요.","options":[{"t":"5","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"4","mis":"M2-2-u2-X17"}],"explanation":["5 × 3은 ○ 5개씩 3묶음, 5 × 4는 5개씩 4묶음이에요.","○ 5개 한 묶음이 더 많아요.","그래서 5 × 4는 5 × 3보다 5만큼 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#3','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'sa','auto','쟁반 5개에 딸기가 5개씩 담겨 있어요. 딸기는 모두 몇 개인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"쟁반 5개에 딸기가 5개씩 담겨 있어요. 딸기는 모두 몇 개인가요?","answer":["25","25개"],"explanation":["5씩 5묶음이에요.","5 + 5 + 5 + 5 + 5 = 25예요.","5 × 5 = 25 — 딸기는 25개예요."],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#4','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'mc','auto','5 + 5 + 5 + 5 + 5 = 25를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X12','M2-2-u2-X11']::text[],false,'{"seq":4,"concept":"M2-2-u2-C2","difficulty":1,"kind":"mc","stem":"5 + 5 + 5 + 5 + 5 = 25를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 × 5 = 25","correct":true},{"t":"5 × 4 = 25","mis":"M2-2-u2-X12"},{"t":"5 + 5 = 25","mis":"M2-2-u2-X11"}],"explanation":["더한 수 5가 몇 개인지 세어요.","5가 5개 — 5씩 5번 더했어요.","그래서 5 × 5 = 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#5','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','5 × 4 = 20이에요. 이것을 이용하여 5 × 5를 구하면 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":5,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5 × 4 = 20이에요. 이것을 이용하여 5 × 5를 구하면 얼마인가요?","options":[{"t":"25","correct":true},{"t":"21","mis":"M2-2-u2-X01"},{"t":"30","mis":"M2-2-u2-X02"}],"explanation":["5 × 5는 5 × 4보다 5만큼 더 커요.","20 + 5 = 25예요.","5씩 한 묶음이 더 많아졌으니 5를 한 번 더 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#6','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'match','auto','쟁반 6개, 7개, 8개에 담긴 딸기의 수를 곱셈식으로 나타냈어요. 곱셈식과 곱을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"M2-2-u2-C2","difficulty":2,"kind":"match","stem":"쟁반 6개, 7개, 8개에 담긴 딸기의 수를 곱셈식으로 나타냈어요. 곱셈식과 곱을 이어 보세요.","pairs":[{"l":"5 × 6","r":"30"},{"l":"5 × 7","r":"35"},{"l":"5 × 8","r":"40"}],"mis":"M2-2-u2-X02","explanation":["5 × 6은 5씩 6번 — 30이에요.","5 × 7은 30보다 5 커서 35, 5 × 8은 40이에요.","쟁반이 하나 늘 때마다 딸기는 5개씩 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#7','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'ox','auto','쟁반이 한 개씩 늘어날수록 딸기는 5개씩 많아져요.',ARRAY['M2-2-u2-X01']::text[],false,'{"seq":7,"concept":"M2-2-u2-C2","difficulty":2,"kind":"ox","stem":"쟁반이 한 개씩 늘어날수록 딸기는 5개씩 많아져요.","answer":"O","reason_options":[{"t":"쟁반 한 개에 딸기가 5개씩 담겨 있으니까","correct":true},{"t":"쟁반이 1개 늘면 딸기도 1개 늘어나니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["쟁반 하나에 딸기 5개예요.","쟁반이 하나 늘면 5개 한 묶음이 더 생겨요.","그래서 5단 곱셈구구의 곱은 5씩 커져요 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#8','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','손가락의 수 맞히기 놀이를 해요. 친구들이 손바닥을 모두 3개 펼쳤어요. 펼친 손가락은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"손가락의 수 맞히기 놀이를 해요. 친구들이 손바닥을 모두 3개 펼쳤어요. 펼친 손가락은 모두 몇 개인가요?","options":[{"t":"15개","correct":true},{"t":"8개","mis":"M2-2-u2-X06"},{"t":"20개","mis":"M2-2-u2-X14"}],"explanation":["손바닥 하나에 손가락이 5개예요.","손바닥 3개는 5씩 3묶음 — 5 × 3 = 15예요.","친구 수가 아니라 펼친 손바닥 수를 세요."],"variant_rule":{"alt":[{"stem":"손가락의 수 맞히기 놀이를 해요. 친구들이 손바닥을 모두 6개 펼쳤어요. 펼친 손가락은 모두 몇 개인가요?","options":[{"t":"30개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"25개","mis":"M2-2-u2-X02"}],"explanation":["손바닥 하나에 손가락 5개예요.","손바닥 6개는 5 × 6 = 30이에요.","5씩 6번 뛰어 세어도 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#9','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','5단 곱셈구구의 곱이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":9,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5단 곱셈구구의 곱이 아닌 것은 어느 것인가요?","options":[{"t":"32","correct":true},{"t":"35","mis":"M2-2-u2-X15"},{"t":"40","mis":"M2-2-u2-X15"}],"explanation":["5단의 곱은 5, 10, 15, 20, 25, 30, 35, 40, 45예요.","5단의 곱은 일의 자리 숫자가 5 아니면 0이에요.","32는 일의 자리 숫자가 2라서 5단의 곱이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_basic#10','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',3,'error','auto','구슬이 5개씩 8묶음 있어요. 구슬의 수를 구하는 방법을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],false,'{"seq":10,"concept":"M2-2-u2-C2","difficulty":3,"kind":"error","stem":"구슬이 5개씩 8묶음 있어요. 구슬의 수를 구하는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"하린: 5 × 7에 8을 더하면 돼.","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"도윤: 5씩 8번 더하면 40개야.","mis":"M2-2-u2-X15"},{"t":"세아: 5 × 7 = 35에 5를 더하면 40개야.","mis":"M2-2-u2-X15"}],"explanation":["구슬은 5 × 8 = 40개예요.","5 × 7에는 곱하는 수 8이 아니라 5를 더해야 해요.","그래서 하린이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#1','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',2,'mc','auto','5단 곱셈구구의 곱에서 일의 자리 숫자는 어떻게 되풀이되나요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":1,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5단 곱셈구구의 곱에서 일의 자리 숫자는 어떻게 되풀이되나요?","options":[{"t":"5, 0, 5, 0, …","correct":true},{"t":"5, 6, 7, 8, …","mis":"M2-2-u2-X16"},{"t":"1, 2, 3, 4, …","mis":"M2-2-u2-X16"}],"explanation":["5단의 곱은 5, 10, 15, 20, 25, …예요.","일의 자리 숫자만 보면 5, 0, 5, 0, …이에요.","곱하는 수의 규칙(1, 2, 3, …)과 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#2','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',2,'ox','auto','5 × 6의 곱은 일의 자리 숫자가 0이에요.',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":2,"kind":"ox","stem":"5 × 6의 곱은 일의 자리 숫자가 0이에요.","answer":"O","reason_options":[{"t":"5 × 6 = 30이라 일의 자리 숫자가 0이니까","correct":true},{"t":"5단의 곱은 일의 자리 숫자가 모두 5니까","mis":"M2-2-u2-X16"}],"mis":"M2-2-u2-X16","explanation":["5 × 6 = 30이에요.","30의 일의 자리 숫자는 0이에요.","5단의 곱은 일의 자리가 5와 0으로 번갈아 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#3','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'sa','auto','손가락의 수 맞히기 놀이에서 친구 4명이 두 손바닥을 모두 펼쳤어요. 펼친 손가락은 모두 몇 개인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u2-C2","difficulty":3,"kind":"sa","stem":"손가락의 수 맞히기 놀이에서 친구 4명이 두 손바닥을 모두 펼쳤어요. 펼친 손가락은 모두 몇 개인가요?","answer":["40","40개"],"explanation":["4명이 두 손바닥씩 — 손바닥은 2 × 4 = 8개예요.","손바닥 하나에 손가락 5개, 8개이니 5 × 8 = 40이에요.","한 손바닥씩만 세면 20개가 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#4','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','손가락의 수 맞히기 놀이에서 4명 가운데 한 명은 손바닥을 펼치지 않고, 두 명은 한 손바닥, 한 명은 두 손바닥을 펼쳤어요. 펼친 손가락은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X05']::text[],false,'{"seq":4,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"손가락의 수 맞히기 놀이에서 4명 가운데 한 명은 손바닥을 펼치지 않고, 두 명은 한 손바닥, 한 명은 두 손바닥을 펼쳤어요. 펼친 손가락은 모두 몇 개인가요?","options":[{"t":"20개","correct":true},{"t":"15개","mis":"M2-2-u2-X18"},{"t":"4개","mis":"M2-2-u2-X05"}],"explanation":["펼친 손바닥은 0 + 1 + 1 + 2 = 4개예요.","손바닥 4개는 5 × 4 = 20이에요.","손바닥 수 4를 답으로 쓰지 말고 손가락을 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#5','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','5 × 8은 5 × 4를 몇 번 더한 것과 같나요?',ARRAY['M2-2-u2-X17','M2-2-u2-X05']::text[],false,'{"seq":5,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"5 × 8은 5 × 4를 몇 번 더한 것과 같나요?","options":[{"t":"2번","correct":true},{"t":"4번","mis":"M2-2-u2-X17"},{"t":"8번","mis":"M2-2-u2-X05"}],"explanation":["5 × 4 = 20이에요.","20 + 20 = 40 = 5 × 8이에요.","5씩 8묶음은 5씩 4묶음이 두 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#6','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'error','auto','5 × 6을 구한 방법이에요. 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],false,'{"seq":6,"concept":"M2-2-u2-C2","difficulty":3,"kind":"error","stem":"5 × 6을 구한 방법이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"라온: 5 × 5 = 25에 6을 더하면 31이야.","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"나은: 5씩 6번 뛰어 세면 30이야.","mis":"M2-2-u2-X15"},{"t":"세아: 5 × 5 = 25에 5를 더하면 30이야.","mis":"M2-2-u2-X15"}],"explanation":["5 × 6은 5 × 5보다 5만큼 더 커요.","라온이는 5 대신 곱하는 수 6을 더했어요.","5 × 6 = 30이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#7','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','5씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"5씩 뛰어 세었어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"31","mis":"M2-2-u2-X01"},{"t":"35","mis":"M2-2-u2-X02"}],"explanation":["5씩 커지는 수예요.","25 다음은 25 + 5 = 30이에요.","30에서 5를 더하면 35 — 다음 칸과 맞아요."],"asset":{"type":"jump_row","cells":[20,25,null,35,40],"step":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#8','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'essay','teacher','5 × 5를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C2","difficulty":4,"kind":"essay","stem":"5 × 5를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예) 5씩 5번 더하면 5 + 5 + 5 + 5 + 5 = 25이다. 5 × 4 = 20에 5를 한 번 더 더하면 25이다.","scoring_points":["동수누가로 25를 구했는가","5 × 4에 5를 더하는 방법으로 25를 구했는가","5 × 5 = 25라고 썼는가"]},"explanation":["5 × 5는 5를 5번 더한 것이에요.","5 × 4보다 5씩 1묶음이 더 많아요.","두 방법 모두 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#9','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'mc','auto','구슬이 한 묶음에 5개씩 7묶음 있었는데, 1묶음을 더 받았어요. 구슬은 모두 몇 개인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X18']::text[],false,'{"seq":9,"concept":"M2-2-u2-C2","difficulty":4,"kind":"mc","stem":"구슬이 한 묶음에 5개씩 7묶음 있었는데, 1묶음을 더 받았어요. 구슬은 모두 몇 개인가요?","options":[{"t":"40개","correct":true},{"t":"36개","mis":"M2-2-u2-X17"},{"t":"35개","mis":"M2-2-u2-X18"}],"explanation":["구슬은 이제 8묶음이에요.","5 × 7 = 35에 5를 더하면 40, 5 × 8 = 40이에요.","받은 1묶음(5개)을 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L03_challenge#10','math',2,2,'u2','L03','tb_g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'essay','teacher','5단 곱셈구구를 완성하고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C2","difficulty":4,"kind":"essay","stem":"5단 곱셈구구를 완성하고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.","answer_guide":{"answer":"예) 5 × 1 = 5, 5 × 2 = 10, …, 5 × 9 = 45. 곱이 5씩 커진다. 곱의 일의 자리 숫자가 5, 0, 5, 0으로 되풀이된다.","scoring_points":["5단 곱셈구구를 바르게 완성했는가","곱이 5씩 커진다는 규칙을 썼는가","일의 자리 숫자가 5와 0으로 되풀이된다는 규칙을 썼는가"]},"explanation":["쟁반이 하나 늘 때마다 딸기가 5개씩 많아져요.","그래서 5단의 곱은 5씩 커져요.","일의 자리 숫자는 5와 0이 번갈아 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#1','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'mc','auto','노란색 물고기가 한 줄에 3마리씩 3줄 모여 있어요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X03']::text[],false,'{"seq":1,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"노란색 물고기가 한 줄에 3마리씩 3줄 모여 있어요. 물고기는 모두 몇 마리인가요?","options":[{"t":"9마리","correct":true},{"t":"6마리","mis":"M2-2-u2-X06"},{"t":"12마리","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 3마리씩, 3줄이에요.","3, 6, 9로 뛰어 세면 9예요.","3 × 3 = 9 — 물고기는 9마리예요."],"asset":{"type":"mul_groups","item":"🐟","k":3,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#2','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'blank','auto','노란색 물고기가 한 줄씩 늘어날 때마다 물고기는 (        )마리씩 많아져요.',ARRAY['M2-2-u2-X01','M2-2-u2-X05']::text[],false,'{"seq":2,"concept":"M2-2-u2-C3","difficulty":1,"kind":"blank","stem":"노란색 물고기가 한 줄씩 늘어날 때마다 물고기는 (        )마리씩 많아져요.","options":[{"t":"3","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"9","mis":"M2-2-u2-X05"}],"explanation":["한 줄에 물고기가 3마리예요.","한 줄이 늘면 3마리가 더 생겨요.","그래서 3단 곱셈구구의 곱은 3씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#3','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'sa','auto','3 × 6을 3씩 6번 더해서 구하면 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"3 × 6을 3씩 6번 더해서 구하면 얼마인가요?","answer":["18"],"explanation":["3 + 3 + 3 + 3 + 3 + 3을 계산해요.","3, 6, 9, 12, 15, 18 — 18이에요.","그래서 3 × 6 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#4','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'mc','auto','노란색 물고기가 한 줄에 3마리씩 8줄 있어요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":4,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"노란색 물고기가 한 줄에 3마리씩 8줄 있어요. 물고기는 모두 몇 마리인가요?","options":[{"t":"24마리","correct":true},{"t":"21마리","mis":"M2-2-u2-X02"},{"t":"11마리","mis":"M2-2-u2-X06"}],"explanation":["3씩 8묶음이에요.","3 × 7 = 21보다 3 커서 3 × 8 = 24예요.","물고기는 24마리예요."],"asset":{"type":"mul_groups","item":"🐟","k":3,"n":8,"look":"rows"},"variant_rule":{"alt":[{"stem":"노란색 물고기가 한 줄에 3마리씩 7줄 있어요. 물고기는 모두 몇 마리인가요?","options":[{"t":"21마리","correct":true},{"t":"18마리","mis":"M2-2-u2-X02"},{"t":"10마리","mis":"M2-2-u2-X06"}],"explanation":["3씩 7묶음이에요.","3 × 6 = 18보다 3 커서 3 × 7 = 21이에요.","물고기는 21마리예요."],"asset":{"type":"mul_groups","item":"🐟","k":3,"n":7,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#5','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','3 × 5 = 15예요. 이것을 이용하여 3 × 6을 구하면 얼마인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X01']::text[],false,'{"seq":5,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"3 × 5 = 15예요. 이것을 이용하여 3 × 6을 구하면 얼마인가요?","options":[{"t":"18","correct":true},{"t":"21","mis":"M2-2-u2-X17"},{"t":"16","mis":"M2-2-u2-X01"}],"explanation":["3 × 6은 3 × 5보다 3만큼 더 커요.","15 + 3 = 18이에요.","한 번 더 더할 때는 곱하는 수 6이 아니라 그 단의 수 3을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#6','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'ox','auto','6 × 4는 6 × 3보다 6만큼 더 커요.',ARRAY['M2-2-u2-X01']::text[],false,'{"seq":6,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 4는 6 × 3보다 6만큼 더 커요.","answer":"O","reason_options":[{"t":"6씩 1묶음이 더 많아지니까","correct":true},{"t":"곱하는 수가 1 커졌으니 1만큼 더 크니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["6 × 3 = 18, 6 × 4 = 24예요.","6씩 한 묶음이 더 많아져서 6만큼 커요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#7','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','6 × 5를 나타낸 그림을 5개씩 묶어 보았더니 5의 6배와 같았어요. 6 × 5의 곱은 얼마인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"6 × 5를 나타낸 그림을 5개씩 묶어 보았더니 5의 6배와 같았어요. 6 × 5의 곱은 얼마인가요?","options":[{"t":"30","correct":true},{"t":"11","mis":"M2-2-u2-X06"},{"t":"36","mis":"M2-2-u2-X02"}],"explanation":["6씩 5묶음을 5개씩 묶으면 5씩 6묶음이 돼요.","5단 곱셈구구를 떠올리면 5 × 6 = 30이에요.","그래서 6 × 5 = 30이에요."],"asset":{"type":"mul_groups","item":"⭐","k":6,"n":5,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#8','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','장난감이 6개씩 4묶음 있어요. 장난감은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":8,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"장난감이 6개씩 4묶음 있어요. 장난감은 모두 몇 개인가요?","options":[{"t":"24개","correct":true},{"t":"10개","mis":"M2-2-u2-X06"},{"t":"30개","mis":"M2-2-u2-X02"}],"explanation":["6씩 4묶음이에요.","6, 12, 18, 24로 뛰어 세면 24예요.","6 × 4 = 24 — 장난감은 24개예요."],"asset":{"type":"mul_groups","item":"🧸","k":6,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#9','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','장난감 24개를 3개씩 묶으면 몇 묶음이 되나요?',ARRAY['M2-2-u2-X10','M2-2-u2-X04']::text[],false,'{"seq":9,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"장난감 24개를 3개씩 묶으면 몇 묶음이 되나요?","options":[{"t":"8묶음","correct":true},{"t":"4묶음","mis":"M2-2-u2-X10"},{"t":"6묶음","mis":"M2-2-u2-X04"}],"explanation":["6개씩 한 묶음은 3개씩 두 묶음이에요.","6개씩 4묶음이니 3개씩 8묶음 — 3 × 8 = 24예요.","3단 곱셈구구로도 장난감의 수를 구할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_basic#10','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',3,'mc','auto','3 × 4 = 12, 6 × 4 = 24예요. 같은 수를 곱할 때 6단의 곱은 3단의 곱의 몇 배인가요?',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":10,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"3 × 4 = 12, 6 × 4 = 24예요. 같은 수를 곱할 때 6단의 곱은 3단의 곱의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"3배","mis":"M2-2-u2-X10"},{"t":"6배","mis":"M2-2-u2-X10"}],"explanation":["24는 12 + 12예요.","6씩 한 묶음은 3씩 두 묶음이에요.","그래서 6단의 곱은 같은 수를 곱한 3단의 곱의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#1','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',2,'mc','auto','학용품 할인 행사에서 공책을 3권씩 묶어 팔아요. 세미는 공책 7묶음을 샀어요. 세미가 산 공책은 모두 몇 권인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":1,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"학용품 할인 행사에서 공책을 3권씩 묶어 팔아요. 세미는 공책 7묶음을 샀어요. 세미가 산 공책은 모두 몇 권인가요?","options":[{"t":"21권","correct":true},{"t":"10권","mis":"M2-2-u2-X06"},{"t":"24권","mis":"M2-2-u2-X02"}],"explanation":["3권씩 7묶음이에요.","3단 곱셈구구로 3 × 7 = 21이에요.","세미가 산 공책은 21권이에요."],"variant_rule":{"alt":[{"stem":"학용품 할인 행사에서 지우개를 6개씩 묶어 팔아요. 지우개 3묶음은 모두 몇 개인가요?","options":[{"t":"18개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"24개","mis":"M2-2-u2-X02"}],"explanation":["6개씩 3묶음이에요.","6 × 3 = 18이에요.","지우개는 18개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#2','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',2,'match','auto','3단과 6단 곱셈구구의 곱셈식과 곱을 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C3","difficulty":2,"kind":"match","stem":"3단과 6단 곱셈구구의 곱셈식과 곱을 이어 보세요.","pairs":[{"l":"3 × 7","r":"21"},{"l":"6 × 6","r":"36"},{"l":"6 × 8","r":"48"}],"mis":"M2-2-u2-X02","explanation":["3 × 7은 3 × 6 = 18보다 3 커서 21이에요.","6 × 6은 36, 6 × 8은 6 × 7 = 42보다 6 커서 48이에요.","곱하는 수가 1 커지면 곱은 그 단의 수만큼 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#3','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','6 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"6 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"6 × 5 = 30에 5를 더해요.","correct":true},{"t":"6을 6번 더해요.","mis":"M2-2-u2-X15"},{"t":"6 × 5 = 30에 6을 더해요.","mis":"M2-2-u2-X15"}],"explanation":["6 × 6 = 36이에요.","6 × 5에 더할 수는 6이에요 — 30 + 5 = 35는 틀려요.","「알맞지 않은」 것을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#4','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','공통된 수 카드 찾기 놀이를 해요. 3단의 곱 카드(3, 6, 9, …, 27)를 보고 6단의 수가 되는 카드에는 「6」이라고 외쳐요. 「6」이라고 외쳐야 하는 카드는 어느 것인가요?',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":4,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"공통된 수 카드 찾기 놀이를 해요. 3단의 곱 카드(3, 6, 9, …, 27)를 보고 6단의 수가 되는 카드에는 「6」이라고 외쳐요. 「6」이라고 외쳐야 하는 카드는 어느 것인가요?","options":[{"t":"18","correct":true},{"t":"15","mis":"M2-2-u2-X10"},{"t":"9","mis":"M2-2-u2-X10"}],"explanation":["6단의 곱은 6, 12, 18, 24, …예요.","3단의 곱 가운데 6단의 곱도 되는 수는 6, 12, 18, 24예요.","그래서 18 카드에 「6」이라고 외쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#5','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'sa','auto','3단의 곱 3, 6, 9, 12, 15, 18, 21, 24, 27 가운데 6단의 곱도 되는 수는 모두 몇 개인가요?','{}'::text[],false,'{"seq":5,"concept":"M2-2-u2-C3","difficulty":3,"kind":"sa","stem":"3단의 곱 3, 6, 9, 12, 15, 18, 21, 24, 27 가운데 6단의 곱도 되는 수는 모두 몇 개인가요?","answer":["4","4개"],"explanation":["6단의 곱은 6, 12, 18, 24, 30, …예요.","27보다 작거나 같은 것은 6, 12, 18, 24예요.","모두 4개 — 3단의 수 두 개마다 하나씩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#6','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','자는 6개씩 1묶음으로 팔아요. 자 3묶음을 3단 곱셈구구로 구하려면 어떤 곱셈식을 쓰면 되나요?',ARRAY['M2-2-u2-X10','M2-2-u2-X14']::text[],false,'{"seq":6,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"자는 6개씩 1묶음으로 팔아요. 자 3묶음을 3단 곱셈구구로 구하려면 어떤 곱셈식을 쓰면 되나요?","options":[{"t":"3 × 6 = 18","correct":true},{"t":"3 × 3 = 9","mis":"M2-2-u2-X10"},{"t":"6 × 6 = 36","mis":"M2-2-u2-X14"}],"explanation":["6개씩 3묶음은 6 × 3 = 18이에요.","6개씩 한 묶음을 3개씩 둘로 나누면 3개씩 6묶음이 돼요.","그래서 3단으로는 3 × 6 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#7','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'ox','auto','6 × 2는 2씩 묶어 2단 곱셈구구로도 구할 수 있어요.',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":7,"concept":"M2-2-u2-C3","difficulty":3,"kind":"ox","stem":"6 × 2는 2씩 묶어 2단 곱셈구구로도 구할 수 있어요.","answer":"O","reason_options":[{"t":"6씩 2묶음을 2씩 묶으면 2씩 6묶음이 되니까","correct":true},{"t":"6단은 6단으로만 구할 수 있으니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["6씩 2묶음은 12개예요.","2개씩 묶으면 2씩 6묶음 — 2 × 6 = 12예요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#8','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'essay','teacher','6 × 6을 여러 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C3","difficulty":4,"kind":"essay","stem":"6 × 6을 여러 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예) 6씩 6번 더하면 36이다. 6 × 5 = 30에 6을 더하면 36이다. 3 × 6 = 18을 두 번 더하면 36이다.","scoring_points":["한 가지 방법으로 36을 바르게 구했는가","다른 방법(한 번 더 더하기·3단의 2배 등)으로도 36을 구했는가","각 방법을 그림이나 식으로 설명했는가"]},"explanation":["6 × 6은 6을 6번 더한 것이에요.","6 × 5보다 6만큼 더 커요.","6씩 한 묶음은 3씩 두 묶음이라 3단의 곱을 두 번 더해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#9','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'mc','auto','노란색 물고기는 한 줄에 3마리씩 4줄, 빨간색 물고기는 한 줄에 6마리씩 4줄 있어요. 빨간색 물고기는 노란색 물고기보다 몇 마리 더 많은가요?',ARRAY['M2-2-u2-X19','M2-2-u2-X06']::text[],false,'{"seq":9,"concept":"M2-2-u2-C3","difficulty":4,"kind":"mc","stem":"노란색 물고기는 한 줄에 3마리씩 4줄, 빨간색 물고기는 한 줄에 6마리씩 4줄 있어요. 빨간색 물고기는 노란색 물고기보다 몇 마리 더 많은가요?","options":[{"t":"12마리","correct":true},{"t":"3마리","mis":"M2-2-u2-X19"},{"t":"36마리","mis":"M2-2-u2-X06"}],"explanation":["노란색 물고기는 3 × 4 = 12마리예요.","빨간색 물고기는 6 × 4 = 24마리예요.","24 − 12 = 12 — 곱을 먼저 구하고 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L04_challenge#10','math',2,2,'u2','L04','tb_g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'essay','teacher','장난감 24개의 수를 6단 곱셈구구와 3단 곱셈구구로 각각 구하는 곱셈식을 쓰고, 두 곱셈구구의 공통점을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C3","difficulty":4,"kind":"essay","stem":"장난감 24개의 수를 6단 곱셈구구와 3단 곱셈구구로 각각 구하는 곱셈식을 쓰고, 두 곱셈구구의 공통점을 설명해 보세요.","answer_guide":{"answer":"예) 6 × 4 = 24, 3 × 8 = 24. 6개씩 한 묶음은 3개씩 두 묶음이라서 6단의 곱은 같은 수를 곱한 3단의 곱의 2배이고, 6단의 곱은 모두 3단의 곱에도 있다.","scoring_points":["6 × 4 = 24를 바르게 썼는가","3 × 8 = 24를 바르게 썼는가","6씩 한 묶음이 3씩 두 묶음이라는 공통점을 설명했는가"]},"explanation":["장난감이 6개씩 4묶음이에요.","같은 장난감을 3개씩 묶으면 8묶음이에요.","6단과 3단은 묶음 크기가 2배 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#1','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'mc','auto','로봇이 한 줄에 4대씩 3줄 서 있어요. 로봇은 모두 몇 대인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X03']::text[],true,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"로봇이 한 줄에 4대씩 3줄 서 있어요. 로봇은 모두 몇 대인가요?","options":[{"t":"12대","correct":true},{"t":"7대","mis":"M2-2-u2-X06"},{"t":"16대","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 4대씩, 3줄이에요.","4, 8, 12로 뛰어 세면 12예요.","4 × 3 = 12 — 로봇은 12대예요."],"asset":{"type":"mul_groups","item":"🤖","k":4,"n":3,"look":"rows"},"variant_rule":{"alt":[{"stem":"학용품 할인 행사에서 연필을 4자루씩 묶어 팔아요. 연필 3묶음은 모두 몇 자루인가요?","options":[{"t":"12자루","correct":true},{"t":"7자루","mis":"M2-2-u2-X06"},{"t":"16자루","mis":"M2-2-u2-X03"}],"explanation":["4자루씩 3묶음이에요.","4 × 3 = 12예요.","연필은 12자루예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#2','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'blank','auto','○를 그려 보면 4 × 4는 4 × 3보다 (        )만큼 더 커요.',ARRAY['M2-2-u2-X01','M2-2-u2-X05']::text[],false,'{"seq":2,"concept":"M2-2-u2-C4","difficulty":1,"kind":"blank","stem":"○를 그려 보면 4 × 4는 4 × 3보다 (        )만큼 더 커요.","options":[{"t":"4","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"16","mis":"M2-2-u2-X05"}],"explanation":["4 × 3은 ○ 4개씩 3묶음, 4 × 4는 4개씩 4묶음이에요.","○ 4개 한 묶음이 더 많아요.","그래서 4 × 4는 4 × 3보다 4만큼 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#3','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'sa','auto','4 + 4 + 4 + 4 + 4 + 4는 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u2-C4","difficulty":1,"kind":"sa","stem":"4 + 4 + 4 + 4 + 4 + 4는 얼마인가요?","answer":["24"],"explanation":["4씩 6번 더해요.","4, 8, 12, 16, 20, 24 — 24예요.","4씩 6번 더한 것은 4 × 6 = 24예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#4','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'match','auto','로봇 7줄, 8줄, 9줄(한 줄에 4대씩)을 곱셈식으로 나타냈어요. 곱셈식과 곱을 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"match","stem":"로봇 7줄, 8줄, 9줄(한 줄에 4대씩)을 곱셈식으로 나타냈어요. 곱셈식과 곱을 이어 보세요.","pairs":[{"l":"4 × 7","r":"28"},{"l":"4 × 8","r":"32"},{"l":"4 × 9","r":"36"}],"mis":"M2-2-u2-X02","explanation":["4 × 7 = 28이에요.","4 × 8은 28보다 4 커서 32, 4 × 9는 36이에요.","로봇이 한 줄 늘 때마다 4대씩 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#5','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','4 × 5 = 20이에요. 이것을 이용하여 4 × 6을 구하면 얼마인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X01']::text[],false,'{"seq":5,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"4 × 5 = 20이에요. 이것을 이용하여 4 × 6을 구하면 얼마인가요?","options":[{"t":"24","correct":true},{"t":"26","mis":"M2-2-u2-X17"},{"t":"21","mis":"M2-2-u2-X01"}],"explanation":["4 × 6은 4 × 5보다 4만큼 더 커요.","20 + 4 = 24예요.","한 번 더 더할 때는 곱하는 수 6이 아니라 그 단의 수 4를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#6','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'ox','auto','8 × 4는 8 × 3보다 8만큼 더 커요.',ARRAY['M2-2-u2-X01']::text[],false,'{"seq":6,"concept":"M2-2-u2-C4","difficulty":2,"kind":"ox","stem":"8 × 4는 8 × 3보다 8만큼 더 커요.","answer":"O","reason_options":[{"t":"8씩 1묶음이 더 많아져서 24에서 32가 되니까","correct":true},{"t":"곱하는 수가 1 커졌으니 1만큼 더 크니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["8 × 3 = 24, 8 × 4 = 32예요.","8씩 한 묶음이 더 많아져 8만큼 커요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#7','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','8 × 5를 나타낸 그림을 5개씩 묶어 보면 5의 8배와 같아요. 8 × 5의 곱은 얼마인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 5를 나타낸 그림을 5개씩 묶어 보면 5의 8배와 같아요. 8 × 5의 곱은 얼마인가요?","options":[{"t":"40","correct":true},{"t":"13","mis":"M2-2-u2-X06"},{"t":"45","mis":"M2-2-u2-X02"}],"explanation":["8씩 5묶음을 5개씩 묶으면 5씩 8묶음이에요.","5단 곱셈구구를 떠올리면 5 × 8 = 40이에요.","그래서 8 × 5 = 40이에요."],"asset":{"type":"mul_groups","item":"⭐","k":8,"n":5,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#8','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','우유가 한 줄에 4갑씩 6줄 있어요(4 × 6 = 24). 같은 우유를 8단 곱셈구구로 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X10','M2-2-u2-X03']::text[],false,'{"seq":8,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"우유가 한 줄에 4갑씩 6줄 있어요(4 × 6 = 24). 같은 우유를 8단 곱셈구구로 구하는 곱셈식은 어느 것인가요?","options":[{"t":"8 × 3 = 24","correct":true},{"t":"8 × 6 = 48","mis":"M2-2-u2-X10"},{"t":"8 × 4 = 32","mis":"M2-2-u2-X03"}],"explanation":["4갑씩 두 줄을 합치면 8갑씩 한 줄이에요.","4갑씩 6줄은 8갑씩 3줄 — 8 × 3 = 24예요.","우유는 모두 24갑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#9','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','로봇이 한 줄에 8대씩 2줄 있어요. 로봇은 모두 몇 대인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":9,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"로봇이 한 줄에 8대씩 2줄 있어요. 로봇은 모두 몇 대인가요?","options":[{"t":"16대","correct":true},{"t":"10대","mis":"M2-2-u2-X06"},{"t":"24대","mis":"M2-2-u2-X02"}],"explanation":["8씩 2묶음이에요.","8 + 8 = 16, 8 × 2 = 16이에요.","로봇은 16대예요."],"asset":{"type":"mul_groups","item":"🤖","k":8,"n":2,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_basic#10','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',3,'mc','auto','로봇 16대를 4단 곱셈구구로 구하려고 해요. 한 줄에 4대씩 놓으면 몇 줄이 되나요?',ARRAY['M2-2-u2-X10','M2-2-u2-X04']::text[],false,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"로봇 16대를 4단 곱셈구구로 구하려고 해요. 한 줄에 4대씩 놓으면 몇 줄이 되나요?","options":[{"t":"4줄","correct":true},{"t":"2줄","mis":"M2-2-u2-X10"},{"t":"8줄","mis":"M2-2-u2-X04"}],"explanation":["로봇 8대는 4대씩 2묶음이에요.","8대씩 2줄은 4대씩 4줄 — 4 × 4 = 16이에요.","그래서 4줄이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#1','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',2,'mc','auto','바둑돌 놀이를 해요. 4 × 2 = 8만큼 놓은 바둑돌을 8개씩 1줄로 다시 놓았어요. 8단 곱셈구구로 나타낸 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"바둑돌 놀이를 해요. 4 × 2 = 8만큼 놓은 바둑돌을 8개씩 1줄로 다시 놓았어요. 8단 곱셈구구로 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"8 × 1 = 8","correct":true},{"t":"8 × 2 = 16","mis":"M2-2-u2-X10"},{"t":"4 × 1 = 4","mis":"M2-2-u2-X10"}],"explanation":["바둑돌은 4 × 2 = 8개예요.","8개씩 1줄로 놓으면 8 × 1 = 8이에요.","바둑돌 수는 그대로이고 묶는 방법만 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#2','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',2,'sa','auto','바둑돌 놀이에서 4 × 6 = 24만큼 놓은 바둑돌을 8개씩 줄로 다시 놓으면 몇 줄이 되나요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C4","difficulty":2,"kind":"sa","stem":"바둑돌 놀이에서 4 × 6 = 24만큼 놓은 바둑돌을 8개씩 줄로 다시 놓으면 몇 줄이 되나요?","answer":["3","3줄"],"explanation":["4개씩 두 줄이 8개씩 한 줄이에요.","4개씩 6줄은 8개씩 3줄이에요.","8 × 3 = 24 — 3줄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#3','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','8 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":3,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"8 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"8 × 3에 3을 더해요.","correct":true},{"t":"8 × 3을 두 번 더해요.","mis":"M2-2-u2-X15"},{"t":"8 × 5 = 40에 8을 더해요.","mis":"M2-2-u2-X15"}],"explanation":["8 × 6 = 48이에요.","8 × 3 = 24를 두 번 더하거나 8 × 5에 8을 더하면 48이에요.","8 × 3에 3을 더하면 27이라 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#4','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','4씩 뛰어 센 수직선이에요. 빈칸 ㉠에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"4씩 뛰어 센 수직선이에요. 빈칸 ㉠에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"5","mis":"M2-2-u2-X01"},{"t":"12","mis":"M2-2-u2-X02"}],"explanation":["4씩 커지는 수예요 — 4, ㉠, 12, 16.","4단 곱셈구구로 4 × 2 = 8이에요.","수찬이처럼 4 × 2 = 8로 생각해요."],"asset":{"type":"jump_row","cells":[4,null,12,16,20],"step":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#5','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'sa','auto','8씩 뛰어 세었더니 8, 16, ㉡이 되었어요. ㉡에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":5,"concept":"M2-2-u2-C4","difficulty":3,"kind":"sa","stem":"8씩 뛰어 세었더니 8, 16, ㉡이 되었어요. ㉡에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["8씩 커지는 수예요.","8단 곱셈구구로 8 × 3 = 24예요.","지아처럼 8 × 3 = 24로 생각해요."],"asset":{"type":"jump_row","cells":[8,16,null],"step":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#6','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'ox','auto','같은 수를 곱할 때 8단의 곱은 4단의 곱의 2배예요.',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":6,"concept":"M2-2-u2-C4","difficulty":3,"kind":"ox","stem":"같은 수를 곱할 때 8단의 곱은 4단의 곱의 2배예요.","answer":"O","reason_options":[{"t":"8씩 한 묶음은 4씩 두 묶음이니까","correct":true},{"t":"4단과 8단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"mis":"M2-2-u2-X10","explanation":["4 × 3 = 12, 8 × 3 = 24예요.","24는 12의 2배예요.","8씩 한 묶음이 4씩 두 묶음이라 그래요 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#7','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','바둑돌 놀이에서 4 × 8 = 32만큼 놓은 바둑돌을 8개씩 줄로 다시 놓았어요. 8단 곱셈구구로 어떻게 나타낼 수 있나요?',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":7,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"바둑돌 놀이에서 4 × 8 = 32만큼 놓은 바둑돌을 8개씩 줄로 다시 놓았어요. 8단 곱셈구구로 어떻게 나타낼 수 있나요?","options":[{"t":"8 × 4 = 32","correct":true},{"t":"8 × 8 = 64","mis":"M2-2-u2-X10"},{"t":"8 × 2 = 16","mis":"M2-2-u2-X10"}],"explanation":["4개씩 두 줄이 8개씩 한 줄이에요.","4개씩 8줄은 8개씩 4줄이에요.","그래서 8 × 4 = 32예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#8','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'essay','teacher','8 × 6을 여러 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C4","difficulty":4,"kind":"essay","stem":"8 × 6을 여러 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예) 8씩 6번 더하면 48이다. 8 × 3 = 24를 두 번 더하면 48이다. 8 × 5 = 40보다 8 크니 48이다.","scoring_points":["한 가지 방법으로 48을 바르게 구했는가","다른 방법으로도 48을 구했는가","각 방법을 그림이나 식으로 설명했는가"]},"explanation":["8 × 6은 8을 6번 더한 것이에요.","8씩 6묶음은 8씩 3묶음이 두 개예요.","8 × 5보다 8만큼 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#9','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'mc','auto','로봇이 왼쪽에 한 줄에 4대씩 5줄, 오른쪽에 한 줄에 8대씩 3줄 있어요. 로봇은 모두 몇 대인가요?',ARRAY['M2-2-u2-X18']::text[],false,'{"seq":9,"concept":"M2-2-u2-C4","difficulty":4,"kind":"mc","stem":"로봇이 왼쪽에 한 줄에 4대씩 5줄, 오른쪽에 한 줄에 8대씩 3줄 있어요. 로봇은 모두 몇 대인가요?","options":[{"t":"44대","correct":true},{"t":"24대","mis":"M2-2-u2-X18"},{"t":"20대","mis":"M2-2-u2-X18"}],"explanation":["왼쪽은 4 × 5 = 20대예요.","오른쪽은 8 × 3 = 24대예요.","20 + 24 = 44 — 두 덩이를 모두 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L05_challenge#10','math',2,2,'u2','L05','tb_g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'essay','teacher','4씩 뛰어 센 수직선 0, 4, ㉠, 12, 16, 20, ㉡에서 수찬이는 ㉠이 8, 지아는 ㉡이 24라고 했어요. 두 친구의 생각을 곱셈구구로 설명하고, 4단과 8단의 관계를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":4,"kind":"essay","stem":"4씩 뛰어 센 수직선 0, 4, ㉠, 12, 16, 20, ㉡에서 수찬이는 ㉠이 8, 지아는 ㉡이 24라고 했어요. 두 친구의 생각을 곱셈구구로 설명하고, 4단과 8단의 관계를 써 보세요.","answer_guide":{"answer":"예) ㉠은 4 × 2 = 8이다. ㉡은 4 × 6 = 24인데 8단으로 보면 8 × 3 = 24이다. 4씩 두 번 뛰면 8씩 한 번 뛴 것과 같아서 8단의 곱은 4단의 곱의 2배이다.","scoring_points":["㉠ = 8을 4 × 2로 설명했는가","㉡ = 24를 8 × 3(또는 4 × 6)으로 설명했는가","4씩 두 번이 8씩 한 번이라는 관계를 썼는가"]},"explanation":["㉠은 4씩 두 번 뛴 자리예요.","㉡은 4씩 여섯 번 — 8씩 세 번 뛴 자리와 같아요.","그래서 4단의 곱에서 8단의 곱을 찾을 수 있어요."],"asset":{"type":"jump_row","cells":[4,null,12,16,20],"step":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#1','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'mc','auto','로봇 경주에서 로봇이 한 칸에 7 cm씩 움직여요. 출발점에서 2칸 갔을 때 이동한 거리는 몇 cm인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":1,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"로봇 경주에서 로봇이 한 칸에 7 cm씩 움직여요. 출발점에서 2칸 갔을 때 이동한 거리는 몇 cm인가요?","options":[{"t":"14 cm","correct":true},{"t":"9 cm","mis":"M2-2-u2-X06"},{"t":"21 cm","mis":"M2-2-u2-X02"}],"explanation":["한 칸에 7 cm — 2칸은 7씩 2묶음이에요.","7 + 7 = 14, 7 × 2 = 14예요.","이동한 거리는 14 cm예요."],"asset":{"type":"jump_row","cells":[7,null,21,28],"step":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#2','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'sa','auto','로봇이 한 칸에 7 cm씩 3칸 이동했어요. 이동한 거리는 몇 cm인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"로봇이 한 칸에 7 cm씩 3칸 이동했어요. 이동한 거리는 몇 cm인가요?","answer":["21","21 cm"],"explanation":["7씩 3묶음이에요.","7, 14, 21로 뛰어 세면 21이에요.","7 × 3 = 21 — 21 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#3','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'mc','auto','7 + 7 + 7 + 7 + 7 = 35를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X12','M2-2-u2-X11']::text[],false,'{"seq":3,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 + 7 + 7 + 7 + 7 = 35를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 × 5 = 35","correct":true},{"t":"7 × 7 = 35","mis":"M2-2-u2-X12"},{"t":"7 + 5 = 12","mis":"M2-2-u2-X11"}],"explanation":["더한 수 7이 몇 개인지 세어요.","7이 5개예요.","그래서 7 × 5 = 35예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#4','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'blank','auto','7단 곱셈구구에서 곱하는 수가 1씩 커지면 곱은 (        )씩 커져요.',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":4,"concept":"M2-2-u2-C5","difficulty":1,"kind":"blank","stem":"7단 곱셈구구에서 곱하는 수가 1씩 커지면 곱은 (        )씩 커져요.","options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"14","mis":"M2-2-u2-X02"}],"explanation":["로봇이 한 칸 더 가면 7 cm 더 가요.","7 × 2 = 14, 7 × 3 = 21 — 7씩 커져요.","그래서 7단의 곱은 7씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#5','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','로봇이 3까지 이동한 거리는 21 cm예요. 5까지 가려면 3에서 두 칸을 더 가야 해요. 로봇이 5까지 이동한 거리는 몇 cm인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X02']::text[],false,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"로봇이 3까지 이동한 거리는 21 cm예요. 5까지 가려면 3에서 두 칸을 더 가야 해요. 로봇이 5까지 이동한 거리는 몇 cm인가요?","options":[{"t":"35 cm","correct":true},{"t":"23 cm","mis":"M2-2-u2-X17"},{"t":"28 cm","mis":"M2-2-u2-X02"}],"explanation":["두 칸을 더 가면 7 × 2 = 14 cm를 더 가요.","21 + 14 = 35예요.","7 × 5 = 35 — 2가 아니라 14를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#6','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','7 × 5 = 35예요. 이것을 이용하여 7 × 6을 구하면 얼마인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X01']::text[],false,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 5 = 35예요. 이것을 이용하여 7 × 6을 구하면 얼마인가요?","options":[{"t":"42","correct":true},{"t":"41","mis":"M2-2-u2-X17"},{"t":"36","mis":"M2-2-u2-X01"}],"explanation":["7 × 6은 7 × 5보다 7만큼 더 커요.","35 + 7 = 42예요.","한 번 더 더할 때는 곱하는 수 6이 아니라 그 단의 수 7을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#7','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'ox','auto','7 × 6은 6개씩 7줄로 생각하여 6 × 7로 구할 수도 있어요.',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":7,"concept":"M2-2-u2-C5","difficulty":2,"kind":"ox","stem":"7 × 6은 6개씩 7줄로 생각하여 6 × 7로 구할 수도 있어요.","answer":"O","reason_options":[{"t":"7개씩 6줄과 6개씩 7줄은 같은 수를 다르게 묶은 것이니까","correct":true},{"t":"두 수를 바꾸어 곱하면 곱이 달라지니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["7개씩 6줄로 놓인 것을 세로로 보면 6개씩 7줄이에요.","6 × 7 = 42, 7 × 6 = 42예요.","묶음 배열을 바꾸어도 전체 수는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#8','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'match','auto','7단 곱셈구구의 곱셈식과 곱을 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C5","difficulty":2,"kind":"match","stem":"7단 곱셈구구의 곱셈식과 곱을 이어 보세요.","pairs":[{"l":"7 × 4","r":"28"},{"l":"7 × 7","r":"49"},{"l":"7 × 9","r":"63"}],"mis":"M2-2-u2-X02","explanation":["7 × 4 = 28이에요.","7 × 7은 7 × 6 = 42보다 7 커서 49예요.","7 × 9는 7 × 8 = 56보다 7 커서 63이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#9','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','로봇이 7 cm씩 이동한 거리를 수직선에 나타냈어요. 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":9,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"로봇이 7 cm씩 이동한 거리를 수직선에 나타냈어요. 빈칸에 알맞은 수는 얼마인가요?","options":[{"t":"35","correct":true},{"t":"29","mis":"M2-2-u2-X01"},{"t":"49","mis":"M2-2-u2-X02"}],"explanation":["7씩 커지는 수예요.","28 다음은 28 + 7 = 35예요.","35 + 7 = 42 — 다음 칸과 맞아요."],"asset":{"type":"jump_row","cells":[21,28,null,42],"step":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_basic#10','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',3,'error','auto','사탕이 한 묶음에 7개씩 6묶음 있어요. 사탕의 수를 구하는 방법을 잘못 말한 사람은 누구인가요?',ARRAY['M2-2-u2-X03','M2-2-u2-X15']::text[],false,'{"seq":10,"concept":"M2-2-u2-C5","difficulty":3,"kind":"error","stem":"사탕이 한 묶음에 7개씩 6묶음 있어요. 사탕의 수를 구하는 방법을 잘못 말한 사람은 누구인가요?","options":[{"t":"지아: 7 × 5 = 35이므로 모두 35개야.","correct":true,"mis_target":"M2-2-u2-X03"},{"t":"연우: 7씩 6번 더하면 구할 수 있어.","mis":"M2-2-u2-X15"},{"t":"재이: 7 × 5에 7을 더해서 구할 수 있어.","mis":"M2-2-u2-X15"}],"explanation":["사탕은 7씩 6묶음 — 7 × 6 = 42개예요.","지아는 5묶음만 세었어요.","연우와 재이처럼 구하면 42개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#1','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',2,'mc','auto','7 × 6을 구하는 방법이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":1,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 6을 구하는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"7 × 5에 6을 더해요.","correct":true},{"t":"7 × 5에 7을 더해요.","mis":"M2-2-u2-X15"},{"t":"6개씩 7줄로 생각해 6 × 7을 구해요.","mis":"M2-2-u2-X15"}],"explanation":["7 × 6 = 42예요.","7 × 5 = 35에 7을 더하거나 6 × 7로 구하면 42예요.","35 + 6 = 41은 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#2','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',2,'sa','auto','7 × 7 = 49예요. 7 × 8은 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C5","difficulty":2,"kind":"sa","stem":"7 × 7 = 49예요. 7 × 8은 얼마인가요?","answer":["56"],"explanation":["7 × 8은 7 × 7보다 7만큼 더 커요.","49 + 7 = 56이에요.","그래서 7 × 8 = 56이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#3','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','로봇이 5칸을 갔어요. 이동한 거리를 7 × 3과 7 × 2로 나누어 구했어요. 이동한 거리는 몇 cm인가요? (한 칸 7 cm)',ARRAY['M2-2-u2-X17','M2-2-u2-X18']::text[],false,'{"seq":3,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"로봇이 5칸을 갔어요. 이동한 거리를 7 × 3과 7 × 2로 나누어 구했어요. 이동한 거리는 몇 cm인가요? (한 칸 7 cm)","options":[{"t":"35 cm","correct":true},{"t":"5 cm","mis":"M2-2-u2-X17"},{"t":"21 cm","mis":"M2-2-u2-X18"}],"explanation":["7 × 3 = 21, 7 × 2 = 14예요.","두 곱을 더하면 21 + 14 = 35예요.","3 + 2 = 5처럼 두 수만 더하거나 한쪽만 세면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#4','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','로봇 두 대가 경주해요. 가 로봇은 7 cm씩 4칸, 나 로봇은 7 cm씩 6칸 갔어요. 나 로봇은 가 로봇보다 몇 cm 더 갔나요?',ARRAY['M2-2-u2-X19','M2-2-u2-X06']::text[],false,'{"seq":4,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"로봇 두 대가 경주해요. 가 로봇은 7 cm씩 4칸, 나 로봇은 7 cm씩 6칸 갔어요. 나 로봇은 가 로봇보다 몇 cm 더 갔나요?","options":[{"t":"14 cm","correct":true},{"t":"2 cm","mis":"M2-2-u2-X19"},{"t":"70 cm","mis":"M2-2-u2-X06"}],"explanation":["가 로봇은 7 × 4 = 28 cm 갔어요.","나 로봇은 7 × 6 = 42 cm 갔어요.","42 − 28 = 14 — 7 cm씩 2칸 더 간 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#5','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'error','auto','7 × 8을 구한 방법이에요. 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],false,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":3,"kind":"error","stem":"7 × 8을 구한 방법이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"은솔: 7 × 7 = 49에 8을 더하면 57이야.","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"예린: 7씩 8번 뛰어 세면 56이야.","mis":"M2-2-u2-X15"},{"t":"태민: 8개씩 7줄로 생각하면 8 × 7 = 56이야.","mis":"M2-2-u2-X15"}],"explanation":["7 × 8은 7 × 7보다 7만큼 더 커요.","은솔이는 7 대신 곱하는 수 8을 더했어요.","7 × 8 = 56이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#6','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'ox','auto','7 × 8은 7 × 4를 두 번 더한 것과 같아요.',ARRAY['M2-2-u2-X17']::text[],false,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":3,"kind":"ox","stem":"7 × 8은 7 × 4를 두 번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"7씩 8묶음은 7씩 4묶음이 두 개라 28 + 28 = 56이니까","correct":true},{"t":"7 × 4에 4를 더하면 7 × 8이 되니까","mis":"M2-2-u2-X17"}],"mis":"M2-2-u2-X17","explanation":["7 × 4 = 28이에요.","28 + 28 = 56 = 7 × 8이에요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#7','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','7 × □ = 42에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"7 × □ = 42에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"}],"explanation":["7단 곱셈구구에서 곱이 42인 것을 찾아요.","7, 14, 21, 28, 35, 42 — 6번째예요.","7 × 6 = 42이니 □는 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#8','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'essay','teacher','7 × 6을 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C5","difficulty":4,"kind":"essay","stem":"7 × 6을 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예) 7 × 5 = 35에 7을 더하면 42이다. 7개씩 6줄을 6개씩 7줄로 생각하면 6 × 7 = 42이다.","scoring_points":["한 번 더 더하기로 42를 구했는가","묶음 배열 바꾸기(6 × 7) 등 다른 방법으로 42를 구했는가","7 × 6 = 42라고 썼는가"]},"explanation":["7 × 6은 7 × 5보다 7만큼 더 커요.","7개씩 6줄은 6개씩 7줄과 같아요.","두 방법 모두 42예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#9','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'mc','auto','로봇이 7 cm씩 9칸을 가려고 해요. 지금 6칸을 갔어요. 앞으로 몇 cm를 더 가야 하나요?',ARRAY['M2-2-u2-X05']::text[],false,'{"seq":9,"concept":"M2-2-u2-C5","difficulty":4,"kind":"mc","stem":"로봇이 7 cm씩 9칸을 가려고 해요. 지금 6칸을 갔어요. 앞으로 몇 cm를 더 가야 하나요?","options":[{"t":"21 cm","correct":true},{"t":"3 cm","mis":"M2-2-u2-X05"},{"t":"63 cm","mis":"M2-2-u2-X05"}],"explanation":["남은 칸은 9 − 6 = 3칸이에요.","3칸은 7 × 3 = 21 cm예요.","남은 칸 수 3이나 전체 거리 63을 답으로 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L06_challenge#10','math',2,2,'u2','L06','tb_g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'essay','teacher','7단 곱셈구구를 완성하고, 7 × 7을 구하는 방법을 한 가지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C5","difficulty":4,"kind":"essay","stem":"7단 곱셈구구를 완성하고, 7 × 7을 구하는 방법을 한 가지 설명해 보세요.","answer_guide":{"answer":"예) 7 × 1 = 7, 7 × 2 = 14, 7 × 3 = 21, 7 × 4 = 28, 7 × 5 = 35, 7 × 6 = 42, 7 × 7 = 49, 7 × 8 = 56, 7 × 9 = 63. 7 × 7은 7 × 6 = 42에 7을 더해 49이다.","scoring_points":["7단 곱셈구구를 바르게 완성했는가","7 × 7을 구하는 방법을 썼는가","곱이 7씩 커진다는 것을 이용했는가"]},"explanation":["7단의 곱은 7씩 커져요.","7 × 7은 7 × 6에 7을 더해요.","로봇이 한 칸 더 가면 7 cm 더 가는 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#1','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'mc','auto','야구공이 한 상자에 9개씩 들어 있어요. 상자 2개에 들어 있는 야구공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":1,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"야구공이 한 상자에 9개씩 들어 있어요. 상자 2개에 들어 있는 야구공은 모두 몇 개인가요?","options":[{"t":"18개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"27개","mis":"M2-2-u2-X02"}],"explanation":["9씩 2묶음이에요.","9 + 9 = 18, 9 × 2 = 18이에요.","야구공은 18개예요."],"asset":{"type":"mul_groups","item":"⚾","k":9,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#2','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'sa','auto','야구공이 한 상자에 9개씩 들어 있어요. 상자 3개에 들어 있는 야구공은 모두 몇 개인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C6","difficulty":1,"kind":"sa","stem":"야구공이 한 상자에 9개씩 들어 있어요. 상자 3개에 들어 있는 야구공은 모두 몇 개인가요?","answer":["27","27개"],"explanation":["9씩 3묶음이에요.","9 × 2 = 18에 9를 더하면 27이에요.","9 × 3 = 27 — 야구공은 27개예요."],"asset":{"type":"mul_groups","item":"⚾","k":9,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#3','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'mc','auto','상자 4개에 들어 있는 야구공의 수를 덧셈식으로 바르게 구한 것은 어느 것인가요? (한 상자에 9개씩)',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],false,'{"seq":3,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"상자 4개에 들어 있는 야구공의 수를 덧셈식으로 바르게 구한 것은 어느 것인가요? (한 상자에 9개씩)","options":[{"t":"9 + 9 + 9 + 9 = 36","correct":true},{"t":"9 + 4 = 13","mis":"M2-2-u2-X11"},{"t":"9 + 9 + 9 = 27","mis":"M2-2-u2-X03"}],"explanation":["9개씩 4상자이니 9를 4번 더해요.","9 + 9 + 9 + 9 = 36이에요.","9 × 4 = 36과 같아요."],"asset":{"type":"mul_groups","item":"⚾","k":9,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#4','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'blank','auto','상자가 1개씩 늘어날 때마다 야구공은 (        )개씩 많아져요.',ARRAY['M2-2-u2-X01','M2-2-u2-X05']::text[],false,'{"seq":4,"concept":"M2-2-u2-C6","difficulty":1,"kind":"blank","stem":"상자가 1개씩 늘어날 때마다 야구공은 (        )개씩 많아져요.","options":[{"t":"9","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"4","mis":"M2-2-u2-X05"}],"explanation":["한 상자에 야구공이 9개예요.","상자가 하나 늘면 9개가 더 생겨요.","그래서 9단 곱셈구구의 곱은 9씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#5','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'mc','auto','9 × 4 = 36이에요. 이것을 이용하여 9 × 5를 구하면 얼마인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X01']::text[],false,'{"seq":5,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × 4 = 36이에요. 이것을 이용하여 9 × 5를 구하면 얼마인가요?","options":[{"t":"45","correct":true},{"t":"41","mis":"M2-2-u2-X17"},{"t":"37","mis":"M2-2-u2-X01"}],"explanation":["9 × 5는 9 × 4보다 9만큼 더 커요.","36 + 9 = 45예요.","한 번 더 더할 때는 곱하는 수 5가 아니라 그 단의 수 9를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#6','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'mc','auto','9 × 2 = 18과 9 × 3 = 27을 이용하여 9 × 5를 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X02']::text[],false,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × 2 = 18과 9 × 3 = 27을 이용하여 9 × 5를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"18과 27을 더해요.","correct":true},{"t":"2와 3을 더해요.","mis":"M2-2-u2-X17"},{"t":"27에 9를 더해요.","mis":"M2-2-u2-X02"}],"explanation":["9씩 5묶음은 9씩 2묶음과 9씩 3묶음이에요.","18 + 27 = 45예요.","두 수 2와 3이 아니라 두 곱을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#7','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'sa','auto','9씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":2,"kind":"sa","stem":"9씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?","answer":["45"],"explanation":["9씩 커지는 수예요.","36 다음은 36 + 9 = 45예요.","9 × 5 = 45예요."],"asset":{"type":"jump_row","cells":[9,18,27,36,null],"step":9}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#8','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'match','auto','9단 곱셈구구의 곱셈식과 곱을 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C6","difficulty":2,"kind":"match","stem":"9단 곱셈구구의 곱셈식과 곱을 이어 보세요.","pairs":[{"l":"9 × 6","r":"54"},{"l":"9 × 7","r":"63"},{"l":"9 × 8","r":"72"}],"mis":"M2-2-u2-X02","explanation":["9 × 6 = 54예요.","9 × 7은 54보다 9 커서 63, 9 × 8은 72예요.","상자가 하나 늘 때마다 야구공은 9개씩 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#9','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'ox','auto','상자 4개에 들어 있는 야구공은 상자 3개에 들어 있는 야구공보다 9개 더 많아요.',ARRAY['M2-2-u2-X01']::text[],false,'{"seq":9,"concept":"M2-2-u2-C6","difficulty":2,"kind":"ox","stem":"상자 4개에 들어 있는 야구공은 상자 3개에 들어 있는 야구공보다 9개 더 많아요.","answer":"O","reason_options":[{"t":"상자 한 개에 야구공이 9개씩 들어 있으니까","correct":true},{"t":"상자가 1개 더 많으니 야구공도 1개 더 많으니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["9 × 3 = 27, 9 × 4 = 36이에요.","36 − 27 = 9예요.","상자 하나에 9개씩이라 9개 더 많아요 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_basic#10','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',3,'mc','auto','9단 곱셈구구의 곱 18, 27, 36, 45에서 십의 자리 숫자와 일의 자리 숫자를 더하면 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":10,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9단 곱셈구구의 곱 18, 27, 36, 45에서 십의 자리 숫자와 일의 자리 숫자를 더하면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"10","mis":"M2-2-u2-X16"},{"t":"곱하는 수와 같아요","mis":"M2-2-u2-X16"}],"explanation":["1 + 8 = 9, 2 + 7 = 9, 3 + 6 = 9, 4 + 5 = 9예요.","모두 9예요.","9단의 곱은 두 숫자의 합이 9라는 규칙이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#1','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',2,'mc','auto','9 × 5를 구하는 방법이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":1,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × 5를 구하는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"9 × 4에 5를 더해요.","correct":true},{"t":"9 × 4에 9를 더해요.","mis":"M2-2-u2-X15"},{"t":"9 × 2와 9 × 3의 곱을 더해요.","mis":"M2-2-u2-X15"}],"explanation":["9 × 5 = 45예요.","36 + 9 = 45, 18 + 27 = 45예요.","36 + 5 = 41은 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#2','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',2,'sa','auto','9 × 8 = 72예요. 9 × 9는 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C6","difficulty":2,"kind":"sa","stem":"9 × 8 = 72예요. 9 × 9는 얼마인가요?","answer":["81"],"explanation":["9 × 9는 9 × 8보다 9만큼 더 커요.","72 + 9 = 81이에요.","그래서 9 × 9 = 81이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#3','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','9단 곱셈구구에서 곱하는 수가 1씩 커질 때 곱의 일의 자리 숫자는 어떻게 되나요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":3,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9단 곱셈구구에서 곱하는 수가 1씩 커질 때 곱의 일의 자리 숫자는 어떻게 되나요?","options":[{"t":"1씩 작아져요","correct":true},{"t":"1씩 커져요","mis":"M2-2-u2-X16"},{"t":"9씩 커져요","mis":"M2-2-u2-X16"}],"explanation":["9, 18, 27, 36, 45 …의 일의 자리 숫자는 9, 8, 7, 6, 5 …예요.","일의 자리 숫자는 1씩 작아져요.","십의 자리 숫자는 1씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#4','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','9단의 규칙(십의 자리 숫자는 곱하는 수보다 1 작고, 두 숫자의 합은 9)으로 9 × 7의 곱을 찾으면 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X16']::text[],false,'{"seq":4,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9단의 규칙(십의 자리 숫자는 곱하는 수보다 1 작고, 두 숫자의 합은 9)으로 9 × 7의 곱을 찾으면 얼마인가요?","options":[{"t":"63","correct":true},{"t":"54","mis":"M2-2-u2-X02"},{"t":"64","mis":"M2-2-u2-X16"}],"explanation":["곱하는 수 7보다 1 작은 6이 십의 자리 숫자예요.","6 + □ = 9이니 일의 자리 숫자는 3이에요.","그래서 9 × 7 = 63이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#5','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','야구공이 한 상자에 9개씩 6상자 있었는데, 그중 2상자를 친구에게 주었어요. 남은 야구공은 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X18']::text[],false,'{"seq":5,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"야구공이 한 상자에 9개씩 6상자 있었는데, 그중 2상자를 친구에게 주었어요. 남은 야구공은 몇 개인가요?","options":[{"t":"36개","correct":true},{"t":"52개","mis":"M2-2-u2-X06"},{"t":"54개","mis":"M2-2-u2-X18"}],"explanation":["남은 상자는 6 − 2 = 4상자예요.","9 × 4 = 36이에요.","54개에서 2개가 아니라 2상자(18개)를 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#6','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'error','auto','9 × 6을 구한 방법이에요. 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],false,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":3,"kind":"error","stem":"9 × 6을 구한 방법이에요. 잘못 구한 친구는 누구인가요?","options":[{"t":"하람: 9 × 5 = 45에 6을 더하면 51이야.","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"지안: 9 × 3 = 27을 두 번 더하면 54야.","mis":"M2-2-u2-X15"},{"t":"아린: 9씩 6번 더하면 54야.","mis":"M2-2-u2-X15"}],"explanation":["9 × 6은 9 × 5보다 9만큼 더 커요.","하람이는 9 대신 곱하는 수 6을 더했어요.","9 × 6 = 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#7','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'sa','auto','9 × □ = 63에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":3,"kind":"sa","stem":"9 × □ = 63에서 □ 안에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["9단 곱셈구구에서 곱이 63인 것을 찾아요.","십의 자리 숫자 6은 곱하는 수보다 1 작아요.","그래서 □는 7 — 9 × 7 = 63이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#8','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'essay','teacher','9 × 5를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C6","difficulty":4,"kind":"essay","stem":"9 × 5를 두 가지 방법으로 계산하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예) 9 × 4 = 36에 9를 더하면 45이다. 9 × 2 = 18과 9 × 3 = 27을 더하면 45이다.","scoring_points":["한 번 더 더하기로 45를 구했는가","부분 서로 더하기(9 × 2와 9 × 3)로 45를 구했는가","9 × 5 = 45라고 썼는가"]},"explanation":["9 × 5는 9 × 4보다 9만큼 더 커요.","9씩 5묶음은 9씩 2묶음과 3묶음으로 나눌 수 있어요.","두 방법 모두 45예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#9','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'mc','auto','9단 곱셈구구의 곱 가운데 50보다 크고 70보다 작은 수는 모두 몇 개인가요?',ARRAY['M2-2-u2-X02']::text[],false,'{"seq":9,"concept":"M2-2-u2-C6","difficulty":4,"kind":"mc","stem":"9단 곱셈구구의 곱 가운데 50보다 크고 70보다 작은 수는 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"3개","mis":"M2-2-u2-X02"},{"t":"1개","mis":"M2-2-u2-X02"}],"explanation":["9단의 곱은 9, 18, 27, 36, 45, 54, 63, 72, 81이에요.","50보다 크고 70보다 작은 수는 54와 63이에요.","그래서 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L07_challenge#10','math',2,2,'u2','L07','tb_g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'essay','teacher','9단 곱셈구구에서 찾을 수 있는 규칙을 두 가지 쓰고, 그 규칙으로 9 × 8의 곱을 확인하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C6","difficulty":4,"kind":"essay","stem":"9단 곱셈구구에서 찾을 수 있는 규칙을 두 가지 쓰고, 그 규칙으로 9 × 8의 곱을 확인하는 방법을 설명해 보세요.","answer_guide":{"answer":"예) 곱하는 수가 1씩 커지면 일의 자리 숫자는 1씩 작아진다. 십의 자리 숫자와 일의 자리 숫자의 합은 9이다. 9 × 8 = 72에서 7은 8보다 1 작고 7 + 2 = 9이다.","scoring_points":["일의 자리 숫자가 1씩 작아지는 규칙을 썼는가","두 숫자의 합이 9라는 규칙을 썼는가","9 × 8 = 72를 규칙으로 확인했는가"]},"explanation":["9단의 곱을 차례로 써 보세요.","일의 자리는 9, 8, 7, …로 작아져요.","십의 자리와 일의 자리 숫자를 더하면 늘 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#1','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','상자 한 개에 인형이 1개씩 들어 있어요. 상자 3개에 들어 있는 인형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],false,'{"seq":1,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"상자 한 개에 인형이 1개씩 들어 있어요. 상자 3개에 들어 있는 인형은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"1개","mis":"M2-2-u2-X08"},{"t":"4개","mis":"M2-2-u2-X06"}],"explanation":["1씩 3묶음이에요.","1 × 3 = 3이에요.","1과 어떤 수의 곱은 그 수예요."],"asset":{"type":"mul_groups","item":"🧸","k":1,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#2','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'sa','auto','상자 한 개에 인형이 1개씩 들어 있어요. 상자 5개에 들어 있는 인형은 모두 몇 개인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":1,"kind":"sa","stem":"상자 한 개에 인형이 1개씩 들어 있어요. 상자 5개에 들어 있는 인형은 모두 몇 개인가요?","answer":["5","5개"],"explanation":["1씩 5묶음이에요.","1 × 5 = 5예요.","상자가 하나 늘 때마다 인형은 1개씩 많아져요."],"asset":{"type":"mul_groups","item":"🧸","k":1,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#3','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','1 × 7은 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],false,'{"seq":3,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"1 × 7은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"8","mis":"M2-2-u2-X06"}],"explanation":["1 × 7은 1을 7번 더한 것이에요.","1 + 1 + 1 + 1 + 1 + 1 + 1 = 7이에요.","1단 곱셈구구는 곱하는 수와 곱이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#4','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','0 × 3은 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],false,'{"seq":4,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"0 × 3은 얼마인가요?","options":[{"t":"0","correct":true},{"t":"3","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}],"explanation":["0 × 3은 0을 3번 더한 것이에요.","0 + 0 + 0 = 0이에요.","0과 어떤 수의 곱은 항상 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#5','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'mc','auto','지아가 공 10개를 던져 과녁에 붙였어요. 과녁에 적힌 수 0, 1, 2, 3에 붙인 공은 3개, 3개, 4개, 0개예요. 3이 적힌 칸에서 얻은 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X11']::text[],false,'{"seq":5,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"지아가 공 10개를 던져 과녁에 붙였어요. 과녁에 적힌 수 0, 1, 2, 3에 붙인 공은 3개, 3개, 4개, 0개예요. 3이 적힌 칸에서 얻은 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3 × 0 = 0","correct":true},{"t":"3 × 0 = 3","mis":"M2-2-u2-X08"},{"t":"3 + 0 = 3","mis":"M2-2-u2-X11"}],"explanation":["3이 적힌 칸에는 공을 하나도 붙이지 못했어요.","3을 한 번도 더하지 않았으니 3 × 0 = 0이에요.","어떤 수와 0의 곱은 항상 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#6','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'sa','auto','지아가 과녁에 붙인 공은 0점 3개, 1점 3개, 2점 4개, 3점 0개예요. 지아가 얻은 점수는 모두 몇 점인가요?','{}'::text[],false,'{"seq":6,"concept":"M2-2-u2-C7","difficulty":2,"kind":"sa","stem":"지아가 과녁에 붙인 공은 0점 3개, 1점 3개, 2점 4개, 3점 0개예요. 지아가 얻은 점수는 모두 몇 점인가요?","answer":["11","11점"],"explanation":["0 × 3 = 0, 1 × 3 = 3, 2 × 4 = 8, 3 × 0 = 0이에요.","0 + 3 + 8 + 0 = 11이에요.","0점 칸과 공이 없는 칸은 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#7','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'mc','auto','재이가 공을 9번 꺼냈어요. 공에 적힌 수 0, 1, 2, 3을 꺼낸 횟수는 2번, 2번, 3번, 2번이에요. 재이가 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X08']::text[],false,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"재이가 공을 9번 꺼냈어요. 공에 적힌 수 0, 1, 2, 3을 꺼낸 횟수는 2번, 2번, 3번, 2번이에요. 재이가 얻은 점수는 모두 몇 점인가요?","options":[{"t":"14점","correct":true},{"t":"9점","mis":"M2-2-u2-X05"},{"t":"16점","mis":"M2-2-u2-X08"}],"explanation":["0 × 2 = 0, 1 × 2 = 2, 2 × 3 = 6, 3 × 2 = 6이에요.","0 + 2 + 6 + 6 = 14예요.","0이 적힌 공은 몇 번 꺼내도 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#8','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'ox','auto','0에 어떤 수를 곱해도, 어떤 수에 0을 곱해도 곱은 항상 0이에요.',ARRAY['M2-2-u2-X08']::text[],false,'{"seq":8,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"0에 어떤 수를 곱해도, 어떤 수에 0을 곱해도 곱은 항상 0이에요.","answer":"O","reason_options":[{"t":"0을 여러 번 더해도 0이고, 어떤 수를 한 번도 더하지 않아도 0이니까","correct":true},{"t":"어떤 수에 0을 곱하면 그 수가 그대로 나오니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08","explanation":["0 × 4 = 0 + 0 + 0 + 0 = 0이에요.","4 × 0은 4를 한 번도 더하지 않은 것이라 0이에요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#9','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'match','auto','1단 곱셈구구와 0의 곱을 계산한 값을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C7","difficulty":2,"kind":"match","stem":"1단 곱셈구구와 0의 곱을 계산한 값을 이어 보세요.","pairs":[{"l":"1 × 4","r":"4"},{"l":"1 × 9","r":"9"},{"l":"0 × 6","r":"0"}],"mis":"M2-2-u2-X08","explanation":["1 × 4 = 4, 1 × 9 = 9 — 1과 어떤 수의 곱은 그 수예요.","0 × 6 = 0 — 0과 어떤 수의 곱은 0이에요.","1단 곱셈표에서 곱하는 수와 곱이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_basic#10','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',3,'mc','auto','세미가 고리 던지기 놀이를 했어요. 고리를 기둥에 걸면 1점, 걸지 못하면 0점이에요. 고리 4개를 걸고 2개는 걸지 못했어요. 세미가 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":10,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"세미가 고리 던지기 놀이를 했어요. 고리를 기둥에 걸면 1점, 걸지 못하면 0점이에요. 고리 4개를 걸고 2개는 걸지 못했어요. 세미가 얻은 점수는 모두 몇 점인가요?","options":[{"t":"4점","correct":true},{"t":"6점","mis":"M2-2-u2-X08"},{"t":"2점","mis":"M2-2-u2-X05"}],"explanation":["건 고리는 1 × 4 = 4점이에요.","걸지 못한 고리는 0 × 2 = 0점이에요.","4 + 0 = 4 — 세미는 4점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#1','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',2,'mc','auto','1단 곱셈표(1 × 1 ~ 1 × 9)에서 찾을 수 있는 규칙은 어느 것인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X16']::text[],false,'{"seq":1,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"1단 곱셈표(1 × 1 ~ 1 × 9)에서 찾을 수 있는 규칙은 어느 것인가요?","options":[{"t":"곱하는 수와 곱이 서로 같아요.","correct":true},{"t":"곱이 항상 1이에요.","mis":"M2-2-u2-X08"},{"t":"곱이 2씩 커져요.","mis":"M2-2-u2-X16"}],"explanation":["1 × 1 = 1, 1 × 2 = 2, 1 × 3 = 3 …이에요.","곱하는 수와 곱이 같아요.","1씩 몇 묶음이면 그 묶음 수만큼이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#2','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',2,'sa','auto','□ × 1 = 8에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":2,"kind":"sa","stem":"□ × 1 = 8에서 □ 안에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["어떤 수와 1의 곱은 그 수예요.","8 × 1 = 8이에요.","그래서 □는 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#3','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 2점에 3번, 0점에 4번 맞혔고 3점에는 한 번도 못 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":3,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 2점에 3번, 0점에 4번 맞혔고 3점에는 한 번도 못 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"6점","correct":true},{"t":"13점","mis":"M2-2-u2-X08"},{"t":"7점","mis":"M2-2-u2-X05"}],"explanation":["2 × 3 = 6, 0 × 4 = 0, 3 × 0 = 0이에요.","6 + 0 + 0 = 6이에요.","맞힌 횟수 7이 점수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#4','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'ox','auto','1 × 0 = 1이에요.',ARRAY['M2-2-u2-X08']::text[],false,'{"seq":4,"concept":"M2-2-u2-C7","difficulty":3,"kind":"ox","stem":"1 × 0 = 1이에요.","answer":"X","reason_options":[{"t":"1을 한 번도 더하지 않았으니 0이니까","correct":true},{"t":"1단 곱셈구구의 곱은 항상 1이니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08","explanation":["어떤 수와 0의 곱은 0이에요.","1 × 0 = 0이에요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#5','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','공 꺼내기 놀이에서 0, 1, 2, 3이 적힌 공을 꺼낸 횟수가 1번, 4번, 0번, 2번이에요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X08']::text[],false,'{"seq":5,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"공 꺼내기 놀이에서 0, 1, 2, 3이 적힌 공을 꺼낸 횟수가 1번, 4번, 0번, 2번이에요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"10점","correct":true},{"t":"7점","mis":"M2-2-u2-X05"},{"t":"11점","mis":"M2-2-u2-X08"}],"explanation":["0 × 1 = 0, 1 × 4 = 4, 2 × 0 = 0, 3 × 2 = 6이에요.","0 + 4 + 0 + 6 = 10이에요.","0이 적힌 공을 꺼낸 것은 1점이 아니라 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#6','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','고리 던지기 놀이(걸면 1점, 못 걸면 0점)에서 고리 7개를 던져 5개를 걸었어요. 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":6,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"고리 던지기 놀이(걸면 1점, 못 걸면 0점)에서 고리 7개를 던져 5개를 걸었어요. 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1 × 5 = 5, 0 × 2 = 0","correct":true},{"t":"1 × 5 = 5, 0 × 2 = 2","mis":"M2-2-u2-X08"},{"t":"1 × 7 = 7","mis":"M2-2-u2-X05"}],"explanation":["건 고리 5개는 1 × 5 = 5점이에요.","못 건 고리 2개는 0 × 2 = 0점이에요.","던진 고리 7개가 모두 1점은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#7','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'sa','auto','0 × □ = 0에서 □ 안에 들어갈 수 있는 수를 1부터 9까지에서 모두 찾으면 몇 개인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":3,"kind":"sa","stem":"0 × □ = 0에서 □ 안에 들어갈 수 있는 수를 1부터 9까지에서 모두 찾으면 몇 개인가요?","answer":["9","9개"],"explanation":["0과 어떤 수의 곱은 항상 0이에요.","1부터 9까지 어떤 수를 넣어도 0이에요.","그래서 9개 모두 들어갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#8','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'essay','teacher','지아가 과녁의 3점 칸에 공을 하나도 붙이지 못했어요. 3점 칸에서 얻은 점수를 곱셈식으로 쓰고, 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C7","difficulty":4,"kind":"essay","stem":"지아가 과녁의 3점 칸에 공을 하나도 붙이지 못했어요. 3점 칸에서 얻은 점수를 곱셈식으로 쓰고, 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예) 3 × 0 = 0이다. 3점을 한 번도 얻지 못했으므로 3을 한 번도 더하지 않은 것이라 0점이다.","scoring_points":["3 × 0 = 0으로 바르게 썼는가","한 번도 맞히지 못하면 점수가 0이라는 까닭을 썼는가","어떤 수와 0의 곱은 0이라고 정리했는가"]},"explanation":["3점 칸에 붙인 공은 0개예요.","3을 0번 더하면 아무것도 없어요.","어떤 수와 0의 곱은 항상 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#9','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'mc','auto','세미와 하람이가 고리를 6개씩 던졌어요. 세미는 4개, 하람이는 2개를 걸었어요. 걸면 1점, 못 걸면 0점일 때 두 사람의 점수는 몇 점 차이가 나나요?',ARRAY['M2-2-u2-X15','M2-2-u2-X08']::text[],false,'{"seq":9,"concept":"M2-2-u2-C7","difficulty":4,"kind":"mc","stem":"세미와 하람이가 고리를 6개씩 던졌어요. 세미는 4개, 하람이는 2개를 걸었어요. 걸면 1점, 못 걸면 0점일 때 두 사람의 점수는 몇 점 차이가 나나요?","options":[{"t":"2점","correct":true},{"t":"6점","mis":"M2-2-u2-X15"},{"t":"0점","mis":"M2-2-u2-X08"}],"explanation":["세미는 1 × 4 + 0 × 2 — 4점이에요.","하람이는 1 × 2 + 0 × 4 — 2점이에요.","4 − 2 = 2 — 2점 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L08_challenge#10','math',2,2,'u2','L08','tb_g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'essay','teacher','1단 곱셈구구와 0의 곱에서 찾은 규칙을 각각 쓰고, 생활 속 예를 하나씩 들어 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C7","difficulty":4,"kind":"essay","stem":"1단 곱셈구구와 0의 곱에서 찾은 규칙을 각각 쓰고, 생활 속 예를 하나씩 들어 보세요.","answer_guide":{"answer":"예) 1과 어떤 수의 곱은 그 수이다 — 상자 한 개에 인형이 1개씩이면 상자 5개에 인형 5개. 0과 어떤 수의 곱, 어떤 수와 0의 곱은 0이다 — 과녁의 0점에 3번 맞히면 0 × 3 = 0점.","scoring_points":["1과 어떤 수의 곱은 그 수라고 썼는가","0의 곱은 항상 0이라고 썼는가","생활 속 예를 알맞게 들었는가"]},"explanation":["1씩 몇 묶음은 그 묶음 수만큼이에요.","0은 여러 번 더해도 0이에요.","어떤 수를 한 번도 더하지 않아도 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#1','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":1,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","options":[{"t":"28","correct":true},{"t":"24","mis":"M2-2-u2-X09"},{"t":"35","mis":"M2-2-u2-X09"}],"explanation":["세로줄의 4와 가로줄의 7이 만나는 칸이에요.","4 × 7 = 28이에요.","이웃 칸(4 × 6 = 24, 5 × 7 = 35)과 헷갈리지 않아요."],"asset":{"type":"gugu_table","rows":[3,4,5],"cols":[5,6,7],"q":[4,7]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈표의 ?에 알맞은 수는 얼마인가요?","options":[{"t":"42","correct":true},{"t":"36","mis":"M2-2-u2-X09"},{"t":"48","mis":"M2-2-u2-X09"}],"explanation":["세로줄의 6과 가로줄의 7이 만나는 칸이에요.","6 × 7 = 42예요.","6 × 6 = 36, 6 × 8 = 48은 이웃 칸이에요."],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[6,7,8],"q":[6,7]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#2','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','곱셈표에서 색칠한 3단 곱셈구구의 곱은 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":2,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표에서 색칠한 3단 곱셈구구의 곱은 얼마씩 커지나요?","options":[{"t":"3","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"6","mis":"M2-2-u2-X02"}],"explanation":["3단의 곱은 3, 6, 9, 12, …예요.","오른쪽으로 한 칸 갈 때마다 3씩 커져요.","곱하는 수가 1 커지면 곱은 3 커져요."],"asset":{"type":"gugu_table","rows":[2,3,4],"cols":[1,2,3,4,5,6,7,8,9],"hrow":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#3','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','곱셈표에서 5단 곱셈구구의 곱의 일의 자리 숫자는 어떻게 되풀이되나요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":3,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표에서 5단 곱셈구구의 곱의 일의 자리 숫자는 어떻게 되풀이되나요?","options":[{"t":"5, 0","correct":true},{"t":"5, 6","mis":"M2-2-u2-X16"},{"t":"1, 2","mis":"M2-2-u2-X16"}],"explanation":["5단의 곱은 5, 10, 15, 20, …예요.","일의 자리 숫자는 5, 0, 5, 0, …이에요.","5와 0이 번갈아 나와요."],"asset":{"type":"gugu_table","rows":[5],"cols":[1,2,3,4,5,6,7,8,9],"hrow":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#4','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'sa','auto','곱셈표에서 세로줄의 6과 가로줄의 4가 만나는 칸에 들어갈 수는 얼마인가요?','{}'::text[],false,'{"seq":4,"concept":"M2-2-u2-C8","difficulty":1,"kind":"sa","stem":"곱셈표에서 세로줄의 6과 가로줄의 4가 만나는 칸에 들어갈 수는 얼마인가요?","answer":["24"],"explanation":["만나는 칸에는 두 수의 곱을 써요.","6 × 4 = 24예요.","6씩 4번 뛰어 세도 24예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#5','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱셈표를 점선을 따라 접었을 때 4 × 7(★)과 만나는 칸은 어느 것인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":5,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표를 점선을 따라 접었을 때 4 × 7(★)과 만나는 칸은 어느 것인가요?","options":[{"t":"7 × 4","correct":true},{"t":"4 × 8","mis":"M2-2-u2-X09"},{"t":"7 × 7","mis":"M2-2-u2-X09"}],"explanation":["점선은 같은 수끼리 곱한 칸(4 × 4, 5 × 5, …)을 이은 선이에요.","접으면 4 × 7과 7 × 4가 만나요.","두 칸 모두 28이에요."],"asset":{"type":"gugu_table","rows":[4,5,6,7],"cols":[4,5,6,7],"diag":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#6','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'ox','auto','4 × 7과 7 × 4는 곱이 같아요.',ARRAY['M2-2-u2-X19']::text[],false,'{"seq":6,"concept":"M2-2-u2-C8","difficulty":2,"kind":"ox","stem":"4 × 7과 7 × 4는 곱이 같아요.","answer":"O","reason_options":[{"t":"두 수를 바꾸어 곱해도 곱은 28로 같으니까","correct":true},{"t":"앞의 수가 큰 7 × 4가 더 크니까","mis":"M2-2-u2-X19"}],"mis":"M2-2-u2-X19","explanation":["4 × 7 = 28이에요.","7 × 4 = 28이에요.","곱하는 두 수의 순서를 바꾸어도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#7','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱셈표에서 8 × 6과 곱이 같은 곱셈구구는 어느 것인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":7,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 8 × 6과 곱이 같은 곱셈구구는 어느 것인가요?","options":[{"t":"6 × 8","correct":true},{"t":"8 × 7","mis":"M2-2-u2-X09"},{"t":"6 × 6","mis":"M2-2-u2-X09"}],"explanation":["8 × 6 = 48이에요.","6 × 8 = 48이에요.","두 수를 바꾸어 곱해도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#8','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱셈표에서 수 찾기 놀이를 해요. 친구들이 「2단 곱셈구구에 있는 수야.」 「4단 곱셈구구에도 있어.」 「3 × 5보다 커.」라고 설명했어요. 이 수는 어느 것인가요?',ARRAY['M2-2-u2-X20']::text[],false,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 수 찾기 놀이를 해요. 친구들이 「2단 곱셈구구에 있는 수야.」 「4단 곱셈구구에도 있어.」 「3 × 5보다 커.」라고 설명했어요. 이 수는 어느 것인가요?","options":[{"t":"16","correct":true},{"t":"12","mis":"M2-2-u2-X20"},{"t":"18","mis":"M2-2-u2-X20"}],"explanation":["2단과 4단에 모두 있는 수는 4, 8, 12, 16이에요.","3 × 5 = 15보다 큰 수는 16이에요.","12는 15보다 작고, 18은 4단에 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#9','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','9 × 4의 곱이 생각나지 않을 때 어떻게 하면 될까요?',ARRAY['M2-2-u2-X09','M2-2-u2-X11']::text[],false,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"9 × 4의 곱이 생각나지 않을 때 어떻게 하면 될까요?","options":[{"t":"4 × 9의 곱을 떠올려요.","correct":true},{"t":"9 × 5의 곱을 떠올려요.","mis":"M2-2-u2-X09"},{"t":"9 + 4를 계산해요.","mis":"M2-2-u2-X11"}],"explanation":["두 수를 바꾸어 곱해도 곱은 같아요.","4 × 9 = 36이니 9 × 4 = 36이에요.","9 + 4는 곱셈이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_basic#10','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',3,'mc','auto','조건에 맞는 수는 어느 것인가요? ① 5단 곱셈구구에 있는 수예요. ② 십의 자리 숫자는 40을 나타내요. ③ 홀수예요.',ARRAY['M2-2-u2-X20']::text[],false,'{"seq":10,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"조건에 맞는 수는 어느 것인가요? ① 5단 곱셈구구에 있는 수예요. ② 십의 자리 숫자는 40을 나타내요. ③ 홀수예요.","options":[{"t":"45","correct":true},{"t":"40","mis":"M2-2-u2-X20"},{"t":"35","mis":"M2-2-u2-X20"}],"explanation":["5단의 곱 가운데 십의 자리 숫자가 4인 수는 40, 45예요.","그중 홀수는 45예요.","조건을 하나씩 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#1','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',2,'mc','auto','곱셈표(1단~9단)에서 곱이 24인 곱셈구구는 모두 몇 개인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":1,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표(1단~9단)에서 곱이 24인 곱셈구구는 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M2-2-u2-X13"},{"t":"1개","mis":"M2-2-u2-X13"}],"explanation":["곱이 24인 칸은 3 × 8, 4 × 6, 6 × 4, 8 × 3이에요.","두 수를 바꾼 것도 따로 세어요.","그래서 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#2','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',2,'mc','auto','4 × 6과 곱이 같은 곱셈구구가 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":2,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"4 × 6과 곱이 같은 곱셈구구가 아닌 것은 어느 것인가요?","options":[{"t":"3 × 9","correct":true},{"t":"6 × 4","mis":"M2-2-u2-X13"},{"t":"3 × 8","mis":"M2-2-u2-X13"}],"explanation":["4 × 6 = 24예요.","6 × 4 = 24, 3 × 8 = 24예요.","3 × 9 = 27이라 곱이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#3','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":3,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","options":[{"t":"21","correct":true},{"t":"24","mis":"M2-2-u2-X09"},{"t":"28","mis":"M2-2-u2-X09"}],"explanation":["세로줄의 3과 가로줄의 7이 만나는 칸이에요.","3 × 7 = 21이에요.","24는 3 × 8의 곱 — 옆 칸의 수를 쓰지 않아요."],"asset":{"type":"gugu_table","rows":[3,4,5],"cols":[6,7,8],"q":[3,7],"blank":[[4,7]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#4','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표(1단~9단)에서 곱이 16인 칸은 모두 몇 칸인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":4,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표(1단~9단)에서 곱이 16인 칸은 모두 몇 칸인가요?","options":[{"t":"3칸","correct":true},{"t":"2칸","mis":"M2-2-u2-X13"},{"t":"4칸","mis":"M2-2-u2-X13"}],"explanation":["곱이 16인 칸은 2 × 8, 4 × 4, 8 × 2예요.","4 × 4는 두 수가 같아서 한 칸뿐이에요.","그래서 모두 3칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#5','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','교과서의 곱셈표에는 0과 곱하는 줄도 있어요. 0과 곱한 줄에 들어가는 수를 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u2-X08']::text[],false,'{"seq":5,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"교과서의 곱셈표에는 0과 곱하는 줄도 있어요. 0과 곱한 줄에 들어가는 수를 바르게 말한 것은 어느 것인가요?","options":[{"t":"모두 0이에요.","correct":true},{"t":"0, 1, 2, 3, …, 9예요.","mis":"M2-2-u2-X08"},{"t":"모두 1이에요.","mis":"M2-2-u2-X08"}],"explanation":["0과 어떤 수의 곱은 0이에요.","0 × 1 = 0, 0 × 2 = 0, … 0 × 9 = 0이에요.","그래서 그 줄은 모두 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#6','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표에서 수 찾기 놀이를 해요. 「6단 곱셈구구에 있는 수야.」 「8단 곱셈구구에도 있어.」 「30보다 작아.」 이 수는 어느 것인가요?',ARRAY['M2-2-u2-X20']::text[],false,'{"seq":6,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표에서 수 찾기 놀이를 해요. 「6단 곱셈구구에 있는 수야.」 「8단 곱셈구구에도 있어.」 「30보다 작아.」 이 수는 어느 것인가요?","options":[{"t":"24","correct":true},{"t":"48","mis":"M2-2-u2-X20"},{"t":"18","mis":"M2-2-u2-X20"}],"explanation":["6단과 8단에 모두 있는 수는 24와 48이에요.","30보다 작은 수는 24예요.","18은 8단에 없고, 48은 30보다 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#7','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'ox','auto','곱셈표에서 3 × 8과 4 × 6은 곱이 같지만 두 수를 바꾼 것은 아니에요.',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":7,"concept":"M2-2-u2-C8","difficulty":3,"kind":"ox","stem":"곱셈표에서 3 × 8과 4 × 6은 곱이 같지만 두 수를 바꾼 것은 아니에요.","answer":"O","reason_options":[{"t":"곱이 24인 곱셈구구는 서로 다른 단에도 있으니까","correct":true},{"t":"곱이 같은 곱셈구구는 두 수를 바꾼 것뿐이니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["3 × 8 = 24, 4 × 6 = 24예요.","두 수를 바꾼 것이 아닌데도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#8','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 수 찾기 놀이를 해요. 36을 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 수 찾기 놀이를 해요. 36을 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.","answer_guide":{"answer":"예) 4단 곱셈구구에 있는 수야. 6 × 6의 곱이야. 9단 곱셈구구에도 있고 7 × 5보다 1 커.","scoring_points":["36이 있는 단을 바르게 말했는가","곱셈식이나 크기 비교로 설명했는가","서로 다른 방법으로 세 가지를 말했는가"]},"explanation":["36은 4 × 9, 6 × 6, 9 × 4의 곱이에요.","어느 단에 있는지, 어떤 곱보다 큰지·작은지로 설명할 수 있어요.","앞 친구와 다른 방법으로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#9','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'mc','auto','어떤 수인지 구해 보세요. ① 3단 곱셈구구에 있는 수예요. ② 홀수예요. ③ 4 × 5보다 크고 5 × 5보다 작아요.',ARRAY['M2-2-u2-X20']::text[],false,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":4,"kind":"mc","stem":"어떤 수인지 구해 보세요. ① 3단 곱셈구구에 있는 수예요. ② 홀수예요. ③ 4 × 5보다 크고 5 × 5보다 작아요.","options":[{"t":"21","correct":true},{"t":"24","mis":"M2-2-u2-X20"},{"t":"27","mis":"M2-2-u2-X20"}],"explanation":["4 × 5 = 20, 5 × 5 = 25 — 20보다 크고 25보다 작은 3단의 수는 21, 24예요.","그중 홀수는 21이에요.","조건을 하나씩 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L09_challenge#10','math',2,2,'u2','L09','tb_g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'essay','teacher','곱셈표를 점선을 따라 접으면 만나는 두 칸의 수가 같아요. 그 까닭을 4 × 7과 7 × 4를 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표를 점선을 따라 접으면 만나는 두 칸의 수가 같아요. 그 까닭을 4 × 7과 7 × 4를 예로 들어 설명해 보세요.","answer_guide":{"answer":"예) 4 × 7은 4씩 7묶음, 7 × 4는 7씩 4묶음이다. 4개씩 7줄로 놓은 것을 옆으로 보면 7개씩 4줄이라 둘 다 28이다. 두 수를 바꾸어 곱해도 곱이 같기 때문에 접으면 같은 수끼리 만난다.","scoring_points":["4 × 7 = 28, 7 × 4 = 28을 썼는가","두 수를 바꾸어 곱해도 곱이 같다고 설명했는가","점선(같은 수끼리 곱한 칸)을 기준으로 접힌다고 썼는가"]},"explanation":["점선은 4 × 4, 5 × 5처럼 같은 수를 곱한 칸이에요.","접으면 4 × 7과 7 × 4가 마주 만나요.","두 수를 바꾸어 곱해도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#1','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','체험관 수족관에 해마가 한 줄에 5마리씩 3줄 있어요. 해마는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X03']::text[],false,'{"seq":1,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"체험관 수족관에 해마가 한 줄에 5마리씩 3줄 있어요. 해마는 모두 몇 마리인가요?","options":[{"t":"15마리","correct":true},{"t":"8마리","mis":"M2-2-u2-X06"},{"t":"20마리","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 5마리씩, 3줄이에요.","5단 곱셈구구로 5 × 3 = 15예요.","해마는 15마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#2','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','해마가 한 줄에 5마리씩 3줄 있어요. 해마의 수를 3단 곱셈구구로 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X04']::text[],false,'{"seq":2,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"해마가 한 줄에 5마리씩 3줄 있어요. 해마의 수를 3단 곱셈구구로 구하는 곱셈식은 어느 것인가요?","options":[{"t":"3 × 5 = 15","correct":true},{"t":"3 × 3 = 9","mis":"M2-2-u2-X04"},{"t":"5 × 5 = 25","mis":"M2-2-u2-X04"}],"explanation":["세로로 보면 3마리씩 5줄이에요.","3 × 5 = 15예요.","5 × 3과 3 × 5는 곱이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#3','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'sa','auto','로봇이 한 줄에 8대씩 2줄 있어요. 로봇은 모두 몇 대인가요?','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C9","difficulty":1,"kind":"sa","stem":"로봇이 한 줄에 8대씩 2줄 있어요. 로봇은 모두 몇 대인가요?","answer":["16","16대"],"explanation":["8씩 2묶음이에요.","8단 곱셈구구로 8 × 2 = 16이에요.","로봇은 16대예요."],"variant_rule":{"alt":[{"stem":"수학이랑 — 사물함이 한 줄에 2칸씩 9줄 있어요. 사물함은 모두 몇 칸인가요?","answer":["18","18칸"],"explanation":["2칸씩 9줄이에요.","2 × 9 = 18이에요.","사물함은 18칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#4','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','곱셈구구를 이용하여 물건의 개수를 알아보면 좋은 점은 어느 것인가요?',ARRAY['M2-2-u2-X21','M2-2-u2-X18']::text[],false,'{"seq":4,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"곱셈구구를 이용하여 물건의 개수를 알아보면 좋은 점은 어느 것인가요?","options":[{"t":"하나씩 세는 것보다 빠르고 편리하게 구할 수 있어요.","correct":true},{"t":"하나씩 세면 답이 틀리기 때문이에요.","mis":"M2-2-u2-X21"},{"t":"물건이 줄 맞춰 있지 않아도 한 번만 곱하면 되기 때문이에요.","mis":"M2-2-u2-X18"}],"explanation":["하나씩 세어도 답은 같아요.","곱셈구구를 쓰면 더 빠르고 편리하게 구할 수 있어요.","줄 맞춰 있지 않으면 나누어 곱하거나 빈자리를 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#5','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','책상이 3개 놓인 줄 하나와 4개씩 놓인 줄 4줄이 있어요. 책상은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18']::text[],false,'{"seq":5,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"책상이 3개 놓인 줄 하나와 4개씩 놓인 줄 4줄이 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"19개","correct":true},{"t":"16개","mis":"M2-2-u2-X18"},{"t":"20개","mis":"M2-2-u2-X18"}],"explanation":["3 × 1 = 3이에요.","4 × 4 = 16이에요.","3과 16을 모두 더하면 19 — 한 덩이를 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#6','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 4 × 5 = 20에서 어떻게 하면 책상의 수가 되나요?',ARRAY['M2-2-u2-X18','M2-2-u2-X03']::text[],false,'{"seq":6,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 4 × 5 = 20에서 어떻게 하면 책상의 수가 되나요?","options":[{"t":"1을 빼요.","correct":true},{"t":"1을 더해요.","mis":"M2-2-u2-X18"},{"t":"5를 빼요.","mis":"M2-2-u2-X03"}],"explanation":["4 × 5 = 20은 빈자리까지 센 수예요.","빈자리 1개를 빼면 19예요.","책상은 19개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#7','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'sa','auto','연결 모형이 3개씩 2줄과 5개씩 4줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?','{}'::text[],false,'{"seq":7,"concept":"M2-2-u2-C9","difficulty":2,"kind":"sa","stem":"연결 모형이 3개씩 2줄과 5개씩 4줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?","answer":["26","26개"],"explanation":["3 × 2 = 6이에요.","5 × 4 = 20이에요.","6과 20을 더하면 26이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#8','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','연결 모형 26개를 5 × 6에서 빼서 구하려고 해요. 5 × 6 = 30에서 몇을 빼야 하나요?',ARRAY['M2-2-u2-X03']::text[],false,'{"seq":8,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"연결 모형 26개를 5 × 6에서 빼서 구하려고 해요. 5 × 6 = 30에서 몇을 빼야 하나요?","options":[{"t":"4","correct":true},{"t":"6","mis":"M2-2-u2-X03"},{"t":"2","mis":"M2-2-u2-X03"}],"explanation":["5개씩 6줄로 채우면 30개예요.","30 − 26 = 4 — 비어 있는 자리가 4개예요.","그래서 30에서 4를 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#9','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','가위바위보를 하여 이기면 6점을 얻는 놀이를 8번 했어요. 재이는 3번 이겼어요. 재이가 얻은 점수는 몇 점인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],false,'{"seq":9,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"가위바위보를 하여 이기면 6점을 얻는 놀이를 8번 했어요. 재이는 3번 이겼어요. 재이가 얻은 점수는 몇 점인가요?","options":[{"t":"18점","correct":true},{"t":"9점","mis":"M2-2-u2-X06"},{"t":"48점","mis":"M2-2-u2-X05"}],"explanation":["한 번 이길 때 6점, 3번 이겼어요.","6 × 3 = 18이에요.","8번 모두 이긴 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_basic#10','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',3,'mc','auto','같은 놀이(이기면 6점)에서 연우는 5번 이겼어요. 연우는 재이(3번 이김)보다 몇 점 더 얻었나요?',ARRAY['M2-2-u2-X19','M2-2-u2-X15']::text[],false,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"같은 놀이(이기면 6점)에서 연우는 5번 이겼어요. 연우는 재이(3번 이김)보다 몇 점 더 얻었나요?","options":[{"t":"12점","correct":true},{"t":"2점","mis":"M2-2-u2-X19"},{"t":"30점","mis":"M2-2-u2-X15"}],"explanation":["연우는 6 × 5 = 30점이에요.","재이는 6 × 3 = 18점이에요.","30 − 18 = 12 — 곱을 먼저 구하고 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#1','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',2,'mc','auto','해마가 한 줄에 5마리씩 3줄 있어요. 해마의 수를 5단과 3단 곱셈구구로 각각 바르게 구한 것은 어느 것인가요?',ARRAY['M2-2-u2-X04','M2-2-u2-X11']::text[],false,'{"seq":1,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"해마가 한 줄에 5마리씩 3줄 있어요. 해마의 수를 5단과 3단 곱셈구구로 각각 바르게 구한 것은 어느 것인가요?","options":[{"t":"5 × 3 = 15, 3 × 5 = 15","correct":true},{"t":"5 × 3 = 15, 3 × 3 = 9","mis":"M2-2-u2-X04"},{"t":"5 + 3 = 8, 3 + 5 = 8","mis":"M2-2-u2-X11"}],"explanation":["가로로 보면 5마리씩 3줄 — 5 × 3 = 15예요.","세로로 보면 3마리씩 5줄 — 3 × 5 = 15예요.","어느 쪽으로 묶어도 15마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#2','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',2,'mc','auto','로봇이 한 줄에 8대씩 2줄 있어요. 로봇의 수를 4단 곱셈구구로 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X10','M2-2-u2-X04']::text[],false,'{"seq":2,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"로봇이 한 줄에 8대씩 2줄 있어요. 로봇의 수를 4단 곱셈구구로 구하는 곱셈식은 어느 것인가요?","options":[{"t":"4 × 4 = 16","correct":true},{"t":"4 × 2 = 8","mis":"M2-2-u2-X10"},{"t":"4 × 8 = 32","mis":"M2-2-u2-X04"}],"explanation":["8대씩 한 줄은 4대씩 두 줄이에요.","8대씩 2줄은 4대씩 4줄 — 4 × 4 = 16이에요.","로봇은 16대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#3','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','연결 모형이 왼쪽에 2개씩 4줄, 오른쪽에 4개씩 3줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18']::text[],false,'{"seq":3,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"연결 모형이 왼쪽에 2개씩 4줄, 오른쪽에 4개씩 3줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"20개","correct":true},{"t":"12개","mis":"M2-2-u2-X18"},{"t":"8개","mis":"M2-2-u2-X18"}],"explanation":["왼쪽은 2 × 4 = 8개예요.","오른쪽은 4 × 3 = 12개예요.","8 + 12 = 20 — 두 덩이로 나누어 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#4','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'error','auto','책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상의 수를 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X15']::text[],false,'{"seq":4,"concept":"M2-2-u2-C9","difficulty":3,"kind":"error","stem":"책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상의 수를 잘못 구한 친구는 누구인가요?","options":[{"t":"도윤: 4 × 5 = 20이니까 20개야.","correct":true,"mis_target":"M2-2-u2-X18"},{"t":"은솔: 4 × 5 = 20에서 1을 빼면 19개야.","mis":"M2-2-u2-X15"},{"t":"예린: 3 × 1 = 3과 4 × 4 = 16을 더하면 19개야.","mis":"M2-2-u2-X15"}],"explanation":["빈자리까지 채우면 4 × 5 = 20개예요.","빈자리 하나를 빼면 19개예요.","도윤이는 빈자리를 빼지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#5','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'sa','auto','의자가 한 줄에 6개씩 4줄로 놓여 있는데 두 자리가 비어 있어요. 의자는 모두 몇 개인가요?','{}'::text[],false,'{"seq":5,"concept":"M2-2-u2-C9","difficulty":3,"kind":"sa","stem":"의자가 한 줄에 6개씩 4줄로 놓여 있는데 두 자리가 비어 있어요. 의자는 모두 몇 개인가요?","answer":["22","22개"],"explanation":["빈자리까지 채우면 6 × 4 = 24개예요.","두 자리가 비었어요.","24 − 2 = 22 — 의자는 22개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#6','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','가위바위보 놀이(이기면 6점)를 8번 했는데 비긴 판은 없었어요. 재이가 3번 이기고 나머지는 연우가 이겼어요. 연우가 얻은 점수는 몇 점인가요?',ARRAY['M2-2-u2-X15','M2-2-u2-X05']::text[],false,'{"seq":6,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"가위바위보 놀이(이기면 6점)를 8번 했는데 비긴 판은 없었어요. 재이가 3번 이기고 나머지는 연우가 이겼어요. 연우가 얻은 점수는 몇 점인가요?","options":[{"t":"30점","correct":true},{"t":"18점","mis":"M2-2-u2-X15"},{"t":"48점","mis":"M2-2-u2-X05"}],"explanation":["연우는 8 − 3 = 5번 이겼어요.","6 × 5 = 30이에요.","18점은 재이의 점수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#7','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'ox','auto','연결 모형의 수를 하나씩 세어 구하는 것은 틀린 방법이에요.',ARRAY['M2-2-u2-X21']::text[],false,'{"seq":7,"concept":"M2-2-u2-C9","difficulty":3,"kind":"ox","stem":"연결 모형의 수를 하나씩 세어 구하는 것은 틀린 방법이에요.","answer":"X","reason_options":[{"t":"하나씩 세어도 답은 같고, 곱셈구구를 쓰면 더 빠르고 편리할 뿐이니까","correct":true},{"t":"곱셈구구로 구하지 않으면 답이 틀리니까","mis":"M2-2-u2-X21"}],"mis":"M2-2-u2-X21","explanation":["하나씩 세도 26개, 곱셈구구로 구해도 26개예요.","곱셈구구는 같은 답을 더 빠르고 편리하게 구하는 방법이에요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#8','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'essay','teacher','연결 모형이 3개씩 2줄과 5개씩 4줄로 붙어 있어요. 연결 모형의 수를 두 가지 방법으로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"연결 모형이 3개씩 2줄과 5개씩 4줄로 붙어 있어요. 연결 모형의 수를 두 가지 방법으로 구하고 설명해 보세요.","answer_guide":{"answer":"예) 3 × 2 = 6과 5 × 4 = 20을 더하면 26개이다. 5개씩 6줄로 채우면 5 × 6 = 30개이고 빈 곳 4개를 빼면 26개이다.","scoring_points":["두 부분으로 나누어 곱한 뒤 더하는 방법으로 26을 구했는가","전체를 채워 곱한 뒤 빼는 방법으로 26을 구했는가","연결 모형이 26개라고 썼는가"]},"explanation":["직사각형이 아닌 모양은 보조선을 그어 나누어요.","나눈 덩이마다 곱하고 더해요.","빈 곳까지 채워 곱한 뒤 빼도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#9','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'mc','auto','사물함이 한 줄에 6칸씩 4줄 있어요. 그중 3칸은 비어 있어요. 물건이 든 사물함은 몇 칸인가요?',ARRAY['M2-2-u2-X18']::text[],false,'{"seq":9,"concept":"M2-2-u2-C9","difficulty":4,"kind":"mc","stem":"사물함이 한 줄에 6칸씩 4줄 있어요. 그중 3칸은 비어 있어요. 물건이 든 사물함은 몇 칸인가요?","options":[{"t":"21칸","correct":true},{"t":"24칸","mis":"M2-2-u2-X18"},{"t":"27칸","mis":"M2-2-u2-X18"}],"explanation":["사물함은 모두 6 × 4 = 24칸이에요.","빈 칸 3칸을 빼요.","24 − 3 = 21칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_L10_challenge#10','math',2,2,'u2','L10','tb_g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'essay','teacher','우리 교실이나 집에서 곱셈구구로 수를 구할 수 있는 상황을 하나 찾아 문제를 만들고, 곱셈구구로 해결해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"우리 교실이나 집에서 곱셈구구로 수를 구할 수 있는 상황을 하나 찾아 문제를 만들고, 곱셈구구로 해결해 보세요.","answer_guide":{"answer":"예) 책꽂이 한 칸에 책이 7권씩 3칸 꽂혀 있다. 책은 모두 몇 권일까? 7 × 3 = 21이므로 21권이다.","scoring_points":["같은 수씩 묶이거나 줄 맞춰 놓인 상황을 찾았는가","한 묶음의 수 × 묶음의 수로 곱셈식을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["사물함, 책꽂이, 공깃돌처럼 같은 수씩 놓인 것을 찾아요.","한 묶음의 수와 묶음의 수를 찾아요.","곱셈구구로 곱을 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#1','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',1,'mc','auto','4 × 4 = 16이에요. 이것을 이용하여 4 × 5를 구하면 얼마인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X01']::text[],false,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"4 × 4 = 16이에요. 이것을 이용하여 4 × 5를 구하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"21","mis":"M2-2-u2-X17"},{"t":"17","mis":"M2-2-u2-X01"}],"explanation":["4 × 5는 4 × 4보다 4만큼 더 커요.","16 + 4 = 20이에요.","한 번 더 더할 때는 곱하는 수 5가 아니라 그 단의 수 4를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#2','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C7',1,'mc','auto','□ × 5 = 5 에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"□ × 5 = 5 에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"1","correct":true},{"t":"0","mis":"M2-2-u2-X08"},{"t":"5","mis":"M2-2-u2-X05"}],"explanation":["1과 어떤 수의 곱, 어떤 수와 1의 곱은 그 수예요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 0이에요.","1 × 5 = 5 — □는 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#3','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',1,'sa','auto','4 × 3 = □ 에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u2-C4","difficulty":1,"kind":"sa","stem":"4 × 3 = □ 에서 □ 안에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["4 × 3은 4를 3번 더한 것이에요.","4 × 3 = 12예요.","곱하는 수가 1 커질 때마다 4씩 커지는 것으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#4','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C1',1,'mc','auto','로봇 한 대에 바퀴가 2개씩, 로봇이 6대 있어요. 바퀴는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":4,"concept":"M2-2-u2-C1","difficulty":1,"kind":"mc","stem":"로봇 한 대에 바퀴가 2개씩, 로봇이 6대 있어요. 바퀴는 모두 몇 개인가요?","options":[{"t":"12개","correct":true},{"t":"8개","mis":"M2-2-u2-X06"},{"t":"14개","mis":"M2-2-u2-X02"}],"explanation":["2씩 6묶음이에요.","2 × 6 = 12예요.","두 수를 더하지 말고 2를 6번 더해요."],"asset":{"type":"mul_groups","item":"⚫","k":2,"n":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#5','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C3',1,'mc','auto','노란색 물고기가 한 줄에 3마리씩 5줄 있어요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":5,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"노란색 물고기가 한 줄에 3마리씩 5줄 있어요. 물고기는 모두 몇 마리인가요?","options":[{"t":"15마리","correct":true},{"t":"8마리","mis":"M2-2-u2-X06"},{"t":"12마리","mis":"M2-2-u2-X02"}],"explanation":["3씩 5묶음이에요.","3 × 5 = 15예요.","곱하는 수가 1 커질 때마다 3씩 커져요."],"asset":{"type":"mul_groups","item":"🐟","k":3,"n":5,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#6','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C5',1,'sa','auto','로봇 경주에서 로봇이 한 칸에 7 cm씩 4칸 이동했어요. 이동한 거리는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"로봇 경주에서 로봇이 한 칸에 7 cm씩 4칸 이동했어요. 이동한 거리는 몇 cm인가요?","answer":["28","28 cm"],"explanation":["7씩 4묶음이에요.","7 × 4 = 28이에요.","이동한 거리는 28 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#7','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C6',1,'mc','auto','야구공이 한 상자에 9개씩 들어 있어요. 상자 5개에 들어 있는 야구공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"야구공이 한 상자에 9개씩 들어 있어요. 상자 5개에 들어 있는 야구공은 모두 몇 개인가요?","options":[{"t":"45개","correct":true},{"t":"14개","mis":"M2-2-u2-X06"},{"t":"36개","mis":"M2-2-u2-X02"}],"explanation":["9씩 5묶음이에요.","9 × 5 = 45예요.","상자가 하나 늘 때마다 야구공은 9개씩 많아져요."],"asset":{"type":"mul_groups","item":"⚾","k":9,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#8','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","options":[{"t":"21","correct":true},{"t":"24","mis":"M2-2-u2-X09"},{"t":"28","mis":"M2-2-u2-X09"}],"explanation":["세로줄의 3과 가로줄의 7이 만나는 칸이에요.","3 × 7 = 21이에요.","이웃 칸의 수와 헷갈리지 않게 두 손가락으로 짚어요."],"asset":{"type":"gugu_table","rows":[2,3,4],"cols":[6,7,8],"q":[3,7]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#9','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 7단 곱셈구구의 곱은 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 7단 곱셈구구의 곱은 얼마씩 커지나요?","options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"14","mis":"M2-2-u2-X02"}],"explanation":["7단의 곱은 7, 14, 21, …예요.","오른쪽으로 한 칸 갈 때마다 7씩 커져요.","곱하는 수가 1 커지면 곱은 그 단의 수만큼 커져요."],"asset":{"type":"gugu_table","rows":[6,7,8],"cols":[1,2,3,4,5,6,7,8,9],"hrow":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#10','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',2,'mc','auto','연결 모형이 3개씩 2줄과 4개씩 3줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18']::text[],false,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"연결 모형이 3개씩 2줄과 4개씩 3줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"18개","correct":true},{"t":"12개","mis":"M2-2-u2-X18"},{"t":"6개","mis":"M2-2-u2-X18"}],"explanation":["3 × 2 = 6이에요.","4 × 3 = 12예요.","두 덩이를 더하면 6 + 12 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#11','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C3',2,'ox','auto','6 × 4는 3 × 4를 두 번 더한 것과 같아요.',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":11,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 4는 3 × 4를 두 번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"6씩 한 묶음은 3씩 두 묶음이라 12 + 12 = 24니까","correct":true},{"t":"3단과 6단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"mis":"M2-2-u2-X10","explanation":["3 × 4 = 12예요.","12 + 12 = 24 = 6 × 4예요.","6단의 곱은 같은 수를 곱한 3단의 곱의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#12','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C3',2,'mc','auto','6 × 5를 나타낸 그림을 5개씩 묶어 보면 5의 몇 배와 같나요?',ARRAY['M2-2-u2-X07','M2-2-u2-X05']::text[],false,'{"seq":12,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"6 × 5를 나타낸 그림을 5개씩 묶어 보면 5의 몇 배와 같나요?","options":[{"t":"6배","correct":true},{"t":"5배","mis":"M2-2-u2-X07"},{"t":"30배","mis":"M2-2-u2-X05"}],"explanation":["6씩 5묶음을 5개씩 다시 묶어요.","5개씩 6묶음 — 5의 6배예요.","그래서 6 × 5 = 5 × 6 = 30이에요."],"asset":{"type":"mul_groups","item":"⭐","k":6,"n":5,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#13','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C7',2,'mc','auto','지아가 공을 던져 과녁의 0, 1, 2, 3점에 붙인 공은 3개, 3개, 4개, 0개예요. 지아가 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X08']::text[],false,'{"seq":13,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"지아가 공을 던져 과녁의 0, 1, 2, 3점에 붙인 공은 3개, 3개, 4개, 0개예요. 지아가 얻은 점수는 모두 몇 점인가요?","options":[{"t":"11점","correct":true},{"t":"10점","mis":"M2-2-u2-X05"},{"t":"14점","mis":"M2-2-u2-X08"}],"explanation":["0 × 3 = 0, 1 × 3 = 3, 2 × 4 = 8, 3 × 0 = 0이에요.","0 + 3 + 8 + 0 = 11이에요.","0점 칸이나 한 번도 못 얻은 점수는 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#14','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 4 × 7과 곱이 같은 곱셈구구는 어느 것인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":14,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 4 × 7과 곱이 같은 곱셈구구는 어느 것인가요?","options":[{"t":"7 × 4","correct":true},{"t":"4 × 8","mis":"M2-2-u2-X09"},{"t":"7 × 7","mis":"M2-2-u2-X09"}],"explanation":["4 × 7 = 28이에요.","7 × 4 = 28이에요.","두 수를 바꾸어 곱해도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#15','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',2,'sa','auto','4씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":15,"concept":"M2-2-u2-C4","difficulty":2,"kind":"sa","stem":"4씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["4씩 커지는 수예요.","빈칸은 4 × 2 = 8이에요.","4씩 두 번 뛰면 8씩 한 번 뛴 것과 같아요."],"asset":{"type":"jump_row","cells":[4,null,12,16],"step":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#16','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C6',2,'mc','auto','9단의 곱은 십의 자리 숫자가 곱하는 수보다 1 작고, 두 숫자의 합이 9예요. 9 × 6의 곱은 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":16,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9단의 곱은 십의 자리 숫자가 곱하는 수보다 1 작고, 두 숫자의 합이 9예요. 9 × 6의 곱은 얼마인가요?","options":[{"t":"54","correct":true},{"t":"45","mis":"M2-2-u2-X16"},{"t":"64","mis":"M2-2-u2-X16"}],"explanation":["십의 자리 숫자는 6보다 1 작은 5예요.","5 + 4 = 9이니 일의 자리 숫자는 4예요.","그래서 9 × 6 = 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#17','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',3,'mc','auto','어떤 수인지 구해 보세요. ① 7단 곱셈구구에 있는 수예요. ② 짝수예요. ③ 9 × 3보다 크고 6 × 6보다 작아요.',ARRAY['M2-2-u2-X20']::text[],false,'{"seq":17,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"어떤 수인지 구해 보세요. ① 7단 곱셈구구에 있는 수예요. ② 짝수예요. ③ 9 × 3보다 크고 6 × 6보다 작아요.","options":[{"t":"28","correct":true},{"t":"14","mis":"M2-2-u2-X20"},{"t":"35","mis":"M2-2-u2-X20"}],"explanation":["9 × 3 = 27, 6 × 6 = 36 — 27보다 크고 36보다 작은 7단의 수는 28, 35예요.","그중 짝수는 28이에요.","14는 범위 밖, 35는 홀수라 조건 하나가 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#18','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',3,'mc','auto','책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X03']::text[],false,'{"seq":18,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"19개","correct":true},{"t":"20개","mis":"M2-2-u2-X18"},{"t":"16개","mis":"M2-2-u2-X03"}],"explanation":["빈자리까지 채우면 4 × 5 = 20개예요.","빈자리 1개를 빼요.","20 − 1 = 19예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#19','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',3,'mc','auto','가위바위보를 하여 이기면 6점을 얻는 놀이를 8번 했어요. 재이는 3번 이겼어요. 재이가 얻은 점수는 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X06']::text[],false,'{"seq":19,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"가위바위보를 하여 이기면 6점을 얻는 놀이를 8번 했어요. 재이는 3번 이겼어요. 재이가 얻은 점수는 몇 점인가요?","options":[{"t":"18점","correct":true},{"t":"48점","mis":"M2-2-u2-X05"},{"t":"9점","mis":"M2-2-u2-X06"}],"explanation":["한 번 이길 때 6점, 3번 이겼어요.","6 × 3 = 18이에요.","놀이한 횟수 8번 모두 이긴 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#20','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C10',3,'mc','auto','곱셈구구 속 비밀을 찾아요. 2단 곱셈구구의 곱의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":20,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"곱셈구구 속 비밀을 찾아요. 2단 곱셈구구의 곱의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"2, 4, 6, 8, 0, 2, 4, 6, 8","correct":true},{"t":"2, 4, 6, 8, 10, 12, 14, 16, 18","mis":"M2-2-u2-X16"},{"t":"1, 2, 3, 4, 5, 6, 7, 8, 9","mis":"M2-2-u2-X16"}],"explanation":["2단의 곱은 2, 4, 6, 8, 10, 12, 14, 16, 18이에요.","일의 자리 숫자만 쓰면 2, 4, 6, 8, 0, 2, 4, 6, 8이에요.","이 숫자를 0~9 활동판에 차례로 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#21','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',3,'mc','auto','곱셈표에서 4 × 6과 곱이 같은 곱셈구구를 빠짐없이 모두 고른 것은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":21,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표에서 4 × 6과 곱이 같은 곱셈구구를 빠짐없이 모두 고른 것은 어느 것인가요?","options":[{"t":"6 × 4, 3 × 8, 8 × 3","correct":true},{"t":"6 × 4","mis":"M2-2-u2-X13"},{"t":"3 × 8, 8 × 3","mis":"M2-2-u2-X13"}],"explanation":["4 × 6 = 24예요.","곱셈표에서 24가 있는 칸을 모두 찾으면 6 × 4, 3 × 8, 8 × 3이에요.","두 수를 바꾼 것과 다른 단의 것까지 모두 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#22','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C5',3,'error','auto','사탕이 한 묶음에 7개씩 6묶음 있어요. 사탕의 수를 구하는 방법을 잘못 말한 사람은 누구인가요?',ARRAY['M2-2-u2-X03','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C5","difficulty":3,"kind":"error","stem":"사탕이 한 묶음에 7개씩 6묶음 있어요. 사탕의 수를 구하는 방법을 잘못 말한 사람은 누구인가요?","options":[{"t":"지아: 7 × 5 = 35이므로 모두 35개야.","correct":true,"mis_target":"M2-2-u2-X03"},{"t":"연우: 7씩 6번 더하면 구할 수 있어.","mis":"M2-2-u2-X15"},{"t":"재이: 7 × 5에 7을 더해서 구할 수 있어.","mis":"M2-2-u2-X15"}],"explanation":["사탕은 7 × 6 = 42개예요.","지아는 5묶음만 세었어요.","그래서 지아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#23','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',4,'essay','teacher','책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상의 수를 두 가지 방법으로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상의 수를 두 가지 방법으로 구하고 설명해 보세요.","answer_guide":{"answer":"예) 3 × 1 = 3과 4 × 4 = 16을 더하면 19개이다. 빈자리까지 채우면 4 × 5 = 20개이고 1을 빼면 19개이다.","scoring_points":["한 가지 방법(나누어 곱하고 더하기 등)으로 바르게 구했는가","다른 방법(채워 곱하고 빼기 등)으로도 구했는가","답을 바르게 썼는가"]},"explanation":["줄 맞춰 놓이지 않은 모양은 보조선을 그어 나누어요.","나눈 덩이마다 곱셈구구로 구해 더해요.","빈자리까지 채워 곱한 뒤 빼도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#24','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C10',4,'essay','teacher','2단과 8단 곱셈구구의 곱의 일의 자리 숫자를 0이 나올 때까지 차례로 쓰고, 0~9 활동판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"2단과 8단 곱셈구구의 곱의 일의 자리 숫자를 0이 나올 때까지 차례로 쓰고, 0~9 활동판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.","answer_guide":{"answer":"예) 2단: 2, 4, 6, 8, 0 / 8단: 8, 6, 4, 2, 0. 같은 숫자들을 순서만 거꾸로 이으므로 같은 무늬가 나온다.","scoring_points":["2단의 일의 자리 숫자를 바르게 썼는가","8단의 일의 자리 숫자를 바르게 썼는가","같은 숫자를 거꾸로 잇기 때문이라고 설명했는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","두 단의 숫자를 나란히 놓고 견주어 봐요.","같은 점들을 반대 방향으로 이으면 같은 무늬가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_a#25','math',2,2,'u2','','tb_g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 수 찾기 놀이를 해요. 16을 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 수 찾기 놀이를 해요. 16을 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.","answer_guide":{"answer":"예) 2단 곱셈구구에 있는 수야. 4단 곱셈구구에도 있어. 3 × 5보다 1 커.","scoring_points":["16이 있는 단을 바르게 말했는가","곱셈식이나 크기 비교로 설명했는가","서로 다른 방법으로 세 가지를 말했는가"]},"explanation":["그 수가 곱셈표의 어느 칸에 있는지 찾아요.","어느 단에 있는지, 어떤 곱보다 큰지·작은지로 말할 수 있어요.","앞 친구와 다른 방법으로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#1','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',1,'mc','auto','4 × 5 = 20이에요. 이것을 이용하여 4 × 6을 구하면 얼마인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X01']::text[],false,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"4 × 5 = 20이에요. 이것을 이용하여 4 × 6을 구하면 얼마인가요?","options":[{"t":"24","correct":true},{"t":"26","mis":"M2-2-u2-X17"},{"t":"21","mis":"M2-2-u2-X01"}],"explanation":["4 × 6은 4 × 5보다 4만큼 더 커요.","20 + 4 = 24예요.","한 번 더 더할 때는 곱하는 수 6이 아니라 그 단의 수 4를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#2','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C7',1,'mc','auto','□ × 8 = 0 에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"□ × 8 = 0 에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"8","mis":"M2-2-u2-X05"}],"explanation":["1과 어떤 수의 곱, 어떤 수와 1의 곱은 그 수예요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 0이에요.","0 × 8 = 0 — □는 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#3','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',1,'sa','auto','8 × 3 = □ 에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u2-C4","difficulty":1,"kind":"sa","stem":"8 × 3 = □ 에서 □ 안에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["8 × 3은 8을 3번 더한 것이에요.","8 × 3 = 24예요.","곱하는 수가 1 커질 때마다 8씩 커지는 것으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#4','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C2',1,'mc','auto','쟁반 한 개에 딸기가 5개씩, 쟁반이 4개 있어요. 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":4,"concept":"M2-2-u2-C2","difficulty":1,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩, 쟁반이 4개 있어요. 딸기는 모두 몇 개인가요?","options":[{"t":"20개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"25개","mis":"M2-2-u2-X02"}],"explanation":["5씩 4묶음이에요.","5 × 4 = 20이에요.","두 수를 더하지 말고 5를 4번 더해요."],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#5','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C3',1,'mc','auto','장난감이 6개씩 3묶음 있어요. 장난감은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":5,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"장난감이 6개씩 3묶음 있어요. 장난감은 모두 몇 개인가요?","options":[{"t":"18개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"12개","mis":"M2-2-u2-X02"}],"explanation":["6씩 3묶음이에요.","6 × 3 = 18이에요.","곱하는 수가 1 커질 때마다 6씩 커져요."],"asset":{"type":"mul_groups","item":"🧸","k":6,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#6','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C5',1,'sa','auto','로봇 경주에서 로봇이 한 칸에 7 cm씩 6칸 이동했어요. 이동한 거리는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"로봇 경주에서 로봇이 한 칸에 7 cm씩 6칸 이동했어요. 이동한 거리는 몇 cm인가요?","answer":["42","42 cm"],"explanation":["7씩 6묶음이에요.","7 × 6 = 42예요.","이동한 거리는 42 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#7','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C6',1,'mc','auto','야구공이 한 상자에 9개씩 들어 있어요. 상자 6개에 들어 있는 야구공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"야구공이 한 상자에 9개씩 들어 있어요. 상자 6개에 들어 있는 야구공은 모두 몇 개인가요?","options":[{"t":"54개","correct":true},{"t":"15개","mis":"M2-2-u2-X06"},{"t":"45개","mis":"M2-2-u2-X02"}],"explanation":["9씩 6묶음이에요.","9 × 6 = 54예요.","상자가 하나 늘 때마다 야구공은 9개씩 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#8','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"36","mis":"M2-2-u2-X09"},{"t":"35","mis":"M2-2-u2-X09"}],"explanation":["세로줄의 6과 가로줄의 5가 만나는 칸이에요.","6 × 5 = 30이에요.","이웃 칸의 수와 헷갈리지 않게 두 손가락으로 짚어요."],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[4,5,6],"q":[6,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#9','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 4단 곱셈구구의 곱은 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 4단 곱셈구구의 곱은 얼마씩 커지나요?","options":[{"t":"4","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X02"}],"explanation":["4단의 곱은 4, 8, 12, …예요.","오른쪽으로 한 칸 갈 때마다 4씩 커져요.","곱하는 수가 1 커지면 곱은 그 단의 수만큼 커져요."],"asset":{"type":"gugu_table","rows":[3,4,5],"cols":[1,2,3,4,5,6,7,8,9],"hrow":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#10','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',2,'mc','auto','연결 모형이 2개씩 4줄과 4개씩 3줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18']::text[],false,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"연결 모형이 2개씩 4줄과 4개씩 3줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"20개","correct":true},{"t":"12개","mis":"M2-2-u2-X18"},{"t":"8개","mis":"M2-2-u2-X18"}],"explanation":["2 × 4 = 8이에요.","4 × 3 = 12예요.","두 덩이를 더하면 8 + 12 = 20이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#11','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',2,'ox','auto','8 × 3은 4 × 3의 2배예요.',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":11,"concept":"M2-2-u2-C4","difficulty":2,"kind":"ox","stem":"8 × 3은 4 × 3의 2배예요.","answer":"O","reason_options":[{"t":"8씩 한 묶음은 4씩 두 묶음이라 12의 2배 24니까","correct":true},{"t":"4단과 8단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"mis":"M2-2-u2-X10","explanation":["4 × 3 = 12, 8 × 3 = 24예요.","24는 12의 2배예요.","8단의 곱은 같은 수를 곱한 4단의 곱의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#12','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',2,'mc','auto','8 × 5를 나타낸 그림을 5개씩 묶어 보면 5의 몇 배와 같나요?',ARRAY['M2-2-u2-X07','M2-2-u2-X05']::text[],false,'{"seq":12,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 5를 나타낸 그림을 5개씩 묶어 보면 5의 몇 배와 같나요?","options":[{"t":"8배","correct":true},{"t":"5배","mis":"M2-2-u2-X07"},{"t":"40배","mis":"M2-2-u2-X05"}],"explanation":["8씩 5묶음을 5개씩 다시 묶어요.","5개씩 8묶음 — 5의 8배예요.","그래서 8 × 5 = 5 × 8 = 40이에요."],"asset":{"type":"mul_groups","item":"⭐","k":8,"n":5,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#13','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C7',2,'mc','auto','재이가 0, 1, 2, 3이 적힌 공을 꺼낸 횟수는 2번, 2번, 3번, 2번이에요. 재이가 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X08']::text[],false,'{"seq":13,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"재이가 0, 1, 2, 3이 적힌 공을 꺼낸 횟수는 2번, 2번, 3번, 2번이에요. 재이가 얻은 점수는 모두 몇 점인가요?","options":[{"t":"14점","correct":true},{"t":"9점","mis":"M2-2-u2-X05"},{"t":"16점","mis":"M2-2-u2-X08"}],"explanation":["0 × 2 = 0, 1 × 2 = 2, 2 × 3 = 6, 3 × 2 = 6이에요.","0 + 2 + 6 + 6 = 14예요.","0점 칸이나 한 번도 못 얻은 점수는 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#14','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 8 × 6과 곱이 같은 곱셈구구는 어느 것인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":14,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 8 × 6과 곱이 같은 곱셈구구는 어느 것인가요?","options":[{"t":"6 × 8","correct":true},{"t":"8 × 7","mis":"M2-2-u2-X09"},{"t":"6 × 6","mis":"M2-2-u2-X09"}],"explanation":["8 × 6 = 48이에요.","6 × 8 = 48이에요.","두 수를 바꾸어 곱해도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#15','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',2,'sa','auto','8씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":15,"concept":"M2-2-u2-C4","difficulty":2,"kind":"sa","stem":"8씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["8씩 커지는 수예요.","빈칸은 8 × 3 = 24예요.","4씩 두 번 뛰면 8씩 한 번 뛴 것과 같아요."],"asset":{"type":"jump_row","cells":[8,16,null,32],"step":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#16','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C6',2,'mc','auto','9단의 곱은 십의 자리 숫자가 곱하는 수보다 1 작고, 두 숫자의 합이 9예요. 9 × 7의 곱은 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":16,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9단의 곱은 십의 자리 숫자가 곱하는 수보다 1 작고, 두 숫자의 합이 9예요. 9 × 7의 곱은 얼마인가요?","options":[{"t":"63","correct":true},{"t":"36","mis":"M2-2-u2-X16"},{"t":"73","mis":"M2-2-u2-X16"}],"explanation":["십의 자리 숫자는 7보다 1 작은 6이에요.","6 + 3 = 9이니 일의 자리 숫자는 3이에요.","그래서 9 × 7 = 63이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#17','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',3,'mc','auto','어떤 수인지 구해 보세요. ① 5단 곱셈구구에 있는 수예요. ② 십의 자리 숫자는 40을 나타내요. ③ 홀수예요.',ARRAY['M2-2-u2-X20']::text[],false,'{"seq":17,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"어떤 수인지 구해 보세요. ① 5단 곱셈구구에 있는 수예요. ② 십의 자리 숫자는 40을 나타내요. ③ 홀수예요.","options":[{"t":"45","correct":true},{"t":"40","mis":"M2-2-u2-X20"},{"t":"35","mis":"M2-2-u2-X20"}],"explanation":["5단의 수 가운데 십의 자리 숫자가 4인 수는 40, 45예요.","그중 홀수는 45예요.","40은 짝수, 35는 십의 자리 숫자가 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#18','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',3,'mc','auto','의자가 한 줄에 6개씩 4줄로 놓여 있는데 두 자리가 비어 있어요. 의자는 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X03']::text[],false,'{"seq":18,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"의자가 한 줄에 6개씩 4줄로 놓여 있는데 두 자리가 비어 있어요. 의자는 모두 몇 개인가요?","options":[{"t":"22개","correct":true},{"t":"24개","mis":"M2-2-u2-X18"},{"t":"18개","mis":"M2-2-u2-X03"}],"explanation":["빈자리까지 채우면 6 × 4 = 24개예요.","빈자리 2개를 빼요.","24 − 2 = 22예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#19','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',3,'mc','auto','가위바위보를 하여 이기면 4점을 얻는 놀이를 9번 했어요. 재이는 5번 이겼어요. 재이가 얻은 점수는 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X06']::text[],false,'{"seq":19,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"가위바위보를 하여 이기면 4점을 얻는 놀이를 9번 했어요. 재이는 5번 이겼어요. 재이가 얻은 점수는 몇 점인가요?","options":[{"t":"20점","correct":true},{"t":"36점","mis":"M2-2-u2-X05"},{"t":"9점","mis":"M2-2-u2-X06"}],"explanation":["한 번 이길 때 4점, 5번 이겼어요.","4 × 5 = 20이에요.","놀이한 횟수 9번 모두 이긴 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#20','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C10',3,'mc','auto','곱셈구구 속 비밀을 찾아요. 6단 곱셈구구의 곱의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":20,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"곱셈구구 속 비밀을 찾아요. 6단 곱셈구구의 곱의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"6, 2, 8, 4, 0, 6, 2, 8, 4","correct":true},{"t":"6, 12, 18, 24, 30, 36, 42, 48, 54","mis":"M2-2-u2-X16"},{"t":"1, 2, 3, 4, 5, 6, 7, 8, 9","mis":"M2-2-u2-X16"}],"explanation":["6단의 곱은 6, 12, 18, 24, 30, 36, 42, 48, 54예요.","일의 자리 숫자만 쓰면 6, 2, 8, 4, 0, 6, 2, 8, 4예요.","이 숫자를 0~9 활동판에 차례로 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#21','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',3,'mc','auto','곱셈표에서 2 × 9와 곱이 같은 곱셈구구를 빠짐없이 모두 고른 것은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":21,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표에서 2 × 9와 곱이 같은 곱셈구구를 빠짐없이 모두 고른 것은 어느 것인가요?","options":[{"t":"9 × 2, 3 × 6, 6 × 3","correct":true},{"t":"9 × 2","mis":"M2-2-u2-X13"},{"t":"3 × 6, 6 × 3","mis":"M2-2-u2-X13"}],"explanation":["2 × 9 = 18이에요.","곱셈표에서 18이 있는 칸을 모두 찾으면 9 × 2, 3 × 6, 6 × 3이에요.","두 수를 바꾼 것과 다른 단의 것까지 모두 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#22','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C5',3,'error','auto','구슬이 7개씩 8묶음 있어요. 구슬의 수를 구하는 방법을 잘못 말한 사람은 누구인가요?',ARRAY['M2-2-u2-X03','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C5","difficulty":3,"kind":"error","stem":"구슬이 7개씩 8묶음 있어요. 구슬의 수를 구하는 방법을 잘못 말한 사람은 누구인가요?","options":[{"t":"서아: 7 × 7 = 49이므로 모두 49개야.","correct":true,"mis_target":"M2-2-u2-X03"},{"t":"준우: 7씩 8번 더하면 구할 수 있어.","mis":"M2-2-u2-X15"},{"t":"라희: 7 × 7에 7을 더해서 구할 수 있어.","mis":"M2-2-u2-X15"}],"explanation":["구슬은 7 × 8 = 56개예요.","서아는 7묶음만 세었어요.","그래서 서아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#23','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',4,'essay','teacher','연결 모형이 3개씩 2줄과 5개씩 4줄로 붙어 있어요. 연결 모형의 수를 두 가지 방법으로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"연결 모형이 3개씩 2줄과 5개씩 4줄로 붙어 있어요. 연결 모형의 수를 두 가지 방법으로 구하고 설명해 보세요.","answer_guide":{"answer":"예) 3 × 2 = 6과 5 × 4 = 20을 더하면 26개이다. 5개씩 6줄로 채우면 5 × 6 = 30개이고 빈 곳 4개를 빼면 26개이다.","scoring_points":["한 가지 방법(나누어 곱하고 더하기 등)으로 바르게 구했는가","다른 방법(채워 곱하고 빼기 등)으로도 구했는가","답을 바르게 썼는가"]},"explanation":["줄 맞춰 놓이지 않은 모양은 보조선을 그어 나누어요.","나눈 덩이마다 곱셈구구로 구해 더해요.","빈자리까지 채워 곱한 뒤 빼도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#24','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C10',4,'essay','teacher','4단과 6단 곱셈구구의 곱의 일의 자리 숫자를 0이 나올 때까지 차례로 쓰고, 0~9 활동판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"4단과 6단 곱셈구구의 곱의 일의 자리 숫자를 0이 나올 때까지 차례로 쓰고, 0~9 활동판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.","answer_guide":{"answer":"예) 4단: 4, 8, 2, 6, 0 / 6단: 6, 2, 8, 4, 0. 같은 숫자들을 순서만 거꾸로 이으므로 같은 무늬가 나온다.","scoring_points":["4단의 일의 자리 숫자를 바르게 썼는가","6단의 일의 자리 숫자를 바르게 썼는가","같은 숫자를 거꾸로 잇기 때문이라고 설명했는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","두 단의 숫자를 나란히 놓고 견주어 봐요.","같은 점들을 반대 방향으로 이으면 같은 무늬가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_b#25','math',2,2,'u2','','tb_g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 수 찾기 놀이를 해요. 24를 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 수 찾기 놀이를 해요. 24를 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.","answer_guide":{"answer":"예) 3단에도 4단에도 있는 수야. 6 × 4의 곱이야. 5 × 5보다 1 작아.","scoring_points":["24가 있는 단을 바르게 말했는가","곱셈식이나 크기 비교로 설명했는가","서로 다른 방법으로 세 가지를 말했는가"]},"explanation":["그 수가 곱셈표의 어느 칸에 있는지 찾아요.","어느 단에 있는지, 어떤 곱보다 큰지·작은지로 말할 수 있어요.","앞 친구와 다른 방법으로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#1','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C4',1,'mc','auto','4 × 7 = 28이에요. 이것을 이용하여 4 × 8을 구하면 얼마인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X01']::text[],false,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"4 × 7 = 28이에요. 이것을 이용하여 4 × 8을 구하면 얼마인가요?","options":[{"t":"32","correct":true},{"t":"36","mis":"M2-2-u2-X17"},{"t":"29","mis":"M2-2-u2-X01"}],"explanation":["4 × 8은 4 × 7보다 4만큼 더 커요.","28 + 4 = 32예요.","한 번 더 더할 때는 곱하는 수 8이 아니라 그 단의 수 4를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#2','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C7',1,'mc','auto','6 × □ = 6 에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"6 × □ = 6 에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"1","correct":true},{"t":"0","mis":"M2-2-u2-X08"},{"t":"6","mis":"M2-2-u2-X05"}],"explanation":["1과 어떤 수의 곱, 어떤 수와 1의 곱은 그 수예요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 0이에요.","6 × 1 = 6 — □는 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#3','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C3',1,'sa','auto','3 × 7 = □ 에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"3 × 7 = □ 에서 □ 안에 알맞은 수는 얼마인가요?","answer":["21"],"explanation":["3 × 7은 3을 7번 더한 것이에요.","3 × 7 = 21이에요.","곱하는 수가 1 커질 때마다 3씩 커지는 것으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#4','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C1',1,'mc','auto','로봇 한 대에 바퀴가 2개씩, 로봇이 8대 있어요. 바퀴는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":4,"concept":"M2-2-u2-C1","difficulty":1,"kind":"mc","stem":"로봇 한 대에 바퀴가 2개씩, 로봇이 8대 있어요. 바퀴는 모두 몇 개인가요?","options":[{"t":"16개","correct":true},{"t":"10개","mis":"M2-2-u2-X06"},{"t":"18개","mis":"M2-2-u2-X02"}],"explanation":["2씩 8묶음이에요.","2 × 8 = 16이에요.","두 수를 더하지 말고 2를 8번 더해요."],"asset":{"type":"mul_groups","item":"⚫","k":2,"n":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#5','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C3',1,'mc','auto','노란색 물고기가 한 줄에 3마리씩 7줄 있어요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":5,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"노란색 물고기가 한 줄에 3마리씩 7줄 있어요. 물고기는 모두 몇 마리인가요?","options":[{"t":"21마리","correct":true},{"t":"10마리","mis":"M2-2-u2-X06"},{"t":"18마리","mis":"M2-2-u2-X02"}],"explanation":["3씩 7묶음이에요.","3 × 7 = 21이에요.","곱하는 수가 1 커질 때마다 3씩 커져요."],"asset":{"type":"mul_groups","item":"🐟","k":3,"n":7,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#6','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C5',1,'sa','auto','로봇 경주에서 로봇이 한 칸에 7 cm씩 8칸 이동했어요. 이동한 거리는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"로봇 경주에서 로봇이 한 칸에 7 cm씩 8칸 이동했어요. 이동한 거리는 몇 cm인가요?","answer":["56","56 cm"],"explanation":["7씩 8묶음이에요.","7 × 8 = 56이에요.","이동한 거리는 56 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#7','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C6',1,'mc','auto','야구공이 한 상자에 9개씩 들어 있어요. 상자 3개에 들어 있는 야구공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"야구공이 한 상자에 9개씩 들어 있어요. 상자 3개에 들어 있는 야구공은 모두 몇 개인가요?","options":[{"t":"27개","correct":true},{"t":"12개","mis":"M2-2-u2-X06"},{"t":"18개","mis":"M2-2-u2-X02"}],"explanation":["9씩 3묶음이에요.","9 × 3 = 27이에요.","상자가 하나 늘 때마다 야구공은 9개씩 많아져요."],"asset":{"type":"mul_groups","item":"⚾","k":9,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#8','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","options":[{"t":"72","correct":true},{"t":"64","mis":"M2-2-u2-X09"},{"t":"63","mis":"M2-2-u2-X09"}],"explanation":["세로줄의 8과 가로줄의 9가 만나는 칸이에요.","8 × 9 = 72예요.","이웃 칸의 수와 헷갈리지 않게 두 손가락으로 짚어요."],"asset":{"type":"gugu_table","rows":[6,7,8],"cols":[7,8,9],"q":[8,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#9','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 6단 곱셈구구의 곱은 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 6단 곱셈구구의 곱은 얼마씩 커지나요?","options":[{"t":"6","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"12","mis":"M2-2-u2-X02"}],"explanation":["6단의 곱은 6, 12, 18, …예요.","오른쪽으로 한 칸 갈 때마다 6씩 커져요.","곱하는 수가 1 커지면 곱은 그 단의 수만큼 커져요."],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[1,2,3,4,5,6,7,8,9],"hrow":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#10','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',2,'mc','auto','연결 모형이 3개씩 2줄과 5개씩 4줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18']::text[],false,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"연결 모형이 3개씩 2줄과 5개씩 4줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"26개","correct":true},{"t":"20개","mis":"M2-2-u2-X18"},{"t":"6개","mis":"M2-2-u2-X18"}],"explanation":["3 × 2 = 6이에요.","5 × 4 = 20이에요.","두 덩이를 더하면 6 + 20 = 26이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#11','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C3',2,'ox','auto','6 × 5는 3 × 5보다 3만큼 더 커요.',ARRAY['M2-2-u2-X19']::text[],false,'{"seq":11,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 5는 3 × 5보다 3만큼 더 커요.","answer":"X","reason_options":[{"t":"6 × 5 = 30은 3 × 5 = 15의 2배라 15만큼 더 크니까","correct":true},{"t":"6이 3보다 3 크니까 곱도 3만큼 크니까","mis":"M2-2-u2-X19"}],"mis":"M2-2-u2-X19","explanation":["3 × 5 = 15, 6 × 5 = 30이에요.","30 − 15 = 15 — 3이 아니라 15만큼 커요.","곱을 먼저 구해 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#12','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 6을 나타낸 그림을 6개씩 묶어 보면 6의 몇 배와 같나요?',ARRAY['M2-2-u2-X07','M2-2-u2-X05']::text[],false,'{"seq":12,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 6을 나타낸 그림을 6개씩 묶어 보면 6의 몇 배와 같나요?","options":[{"t":"7배","correct":true},{"t":"6배","mis":"M2-2-u2-X07"},{"t":"42배","mis":"M2-2-u2-X05"}],"explanation":["7씩 6묶음을 6개씩 다시 묶어요.","6개씩 7묶음 — 6의 7배예요.","그래서 7 × 6 = 6 × 7 = 42예요."],"asset":{"type":"mul_groups","item":"⭐","k":7,"n":6,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#13','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C7',2,'mc','auto','지아가 공을 던져 과녁의 0, 1, 2, 3점에 붙인 공은 4개, 1개, 2개, 2개예요. 지아가 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X08']::text[],false,'{"seq":13,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"지아가 공을 던져 과녁의 0, 1, 2, 3점에 붙인 공은 4개, 1개, 2개, 2개예요. 지아가 얻은 점수는 모두 몇 점인가요?","options":[{"t":"11점","correct":true},{"t":"9점","mis":"M2-2-u2-X05"},{"t":"15점","mis":"M2-2-u2-X08"}],"explanation":["0 × 4 = 0, 1 × 1 = 1, 2 × 2 = 4, 3 × 2 = 6이에요.","0 + 1 + 4 + 6 = 11이에요.","0점 칸이나 한 번도 못 얻은 점수는 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#14','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 3 × 9와 곱이 같은 곱셈구구는 어느 것인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":14,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 3 × 9와 곱이 같은 곱셈구구는 어느 것인가요?","options":[{"t":"9 × 3","correct":true},{"t":"3 × 8","mis":"M2-2-u2-X09"},{"t":"9 × 9","mis":"M2-2-u2-X09"}],"explanation":["3 × 9 = 27이에요.","9 × 3 = 27이에요.","두 수를 바꾸어 곱해도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#15','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C4',2,'sa','auto','4씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":15,"concept":"M2-2-u2-C4","difficulty":2,"kind":"sa","stem":"4씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?","answer":["20"],"explanation":["4씩 커지는 수예요.","빈칸은 4 × 5 = 20이에요.","4씩 두 번 뛰면 8씩 한 번 뛴 것과 같아요."],"asset":{"type":"jump_row","cells":[12,16,null,24],"step":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#16','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C6',2,'mc','auto','9단의 곱은 십의 자리 숫자가 곱하는 수보다 1 작고, 두 숫자의 합이 9예요. 9 × 8의 곱은 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":16,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9단의 곱은 십의 자리 숫자가 곱하는 수보다 1 작고, 두 숫자의 합이 9예요. 9 × 8의 곱은 얼마인가요?","options":[{"t":"72","correct":true},{"t":"27","mis":"M2-2-u2-X16"},{"t":"82","mis":"M2-2-u2-X16"}],"explanation":["십의 자리 숫자는 8보다 1 작은 7이에요.","7 + 2 = 9이니 일의 자리 숫자는 2예요.","그래서 9 × 8 = 72예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#17','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',3,'mc','auto','어떤 수인지 구해 보세요. ① 6단 곱셈구구에 있는 수예요. ② 8단 곱셈구구에도 있어요. ③ 30보다 작아요.',ARRAY['M2-2-u2-X20']::text[],false,'{"seq":17,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"어떤 수인지 구해 보세요. ① 6단 곱셈구구에 있는 수예요. ② 8단 곱셈구구에도 있어요. ③ 30보다 작아요.","options":[{"t":"24","correct":true},{"t":"48","mis":"M2-2-u2-X20"},{"t":"18","mis":"M2-2-u2-X20"}],"explanation":["6단과 8단에 모두 있는 수는 24, 48이에요.","30보다 작은 수는 24예요.","48은 30보다 크고, 18은 8단에 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#18','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',3,'mc','auto','책상이 한 줄에 5개씩 6줄로 놓여 있는데 두 자리가 비어 있어요. 책상은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X03']::text[],false,'{"seq":18,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"책상이 한 줄에 5개씩 6줄로 놓여 있는데 두 자리가 비어 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"28개","correct":true},{"t":"30개","mis":"M2-2-u2-X18"},{"t":"25개","mis":"M2-2-u2-X03"}],"explanation":["빈자리까지 채우면 5 × 6 = 30개예요.","빈자리 2개를 빼요.","30 − 2 = 28이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#19','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',3,'mc','auto','가위바위보를 하여 이기면 3점을 얻는 놀이를 7번 했어요. 재이는 6번 이겼어요. 재이가 얻은 점수는 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X06']::text[],false,'{"seq":19,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"가위바위보를 하여 이기면 3점을 얻는 놀이를 7번 했어요. 재이는 6번 이겼어요. 재이가 얻은 점수는 몇 점인가요?","options":[{"t":"18점","correct":true},{"t":"21점","mis":"M2-2-u2-X05"},{"t":"9점","mis":"M2-2-u2-X06"}],"explanation":["한 번 이길 때 3점, 6번 이겼어요.","3 × 6 = 18이에요.","놀이한 횟수 7번 모두 이긴 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#20','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C10',3,'mc','auto','곱셈구구 속 비밀을 찾아요. 4단 곱셈구구의 곱의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":20,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"곱셈구구 속 비밀을 찾아요. 4단 곱셈구구의 곱의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"4, 8, 2, 6, 0, 4, 8, 2, 6","correct":true},{"t":"4, 8, 12, 16, 20, 24, 28, 32, 36","mis":"M2-2-u2-X16"},{"t":"1, 2, 3, 4, 5, 6, 7, 8, 9","mis":"M2-2-u2-X16"}],"explanation":["4단의 곱은 4, 8, 12, 16, 20, 24, 28, 32, 36이에요.","일의 자리 숫자만 쓰면 4, 8, 2, 6, 0, 4, 8, 2, 6이에요.","이 숫자를 0~9 활동판에 차례로 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#21','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',3,'mc','auto','곱셈표에서 3 × 4와 곱이 같은 곱셈구구를 빠짐없이 모두 고른 것은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":21,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표에서 3 × 4와 곱이 같은 곱셈구구를 빠짐없이 모두 고른 것은 어느 것인가요?","options":[{"t":"4 × 3, 2 × 6, 6 × 2","correct":true},{"t":"4 × 3","mis":"M2-2-u2-X13"},{"t":"2 × 6, 6 × 2","mis":"M2-2-u2-X13"}],"explanation":["3 × 4 = 12예요.","곱셈표에서 12가 있는 칸을 모두 찾으면 4 × 3, 2 × 6, 6 × 2예요.","두 수를 바꾼 것과 다른 단의 것까지 모두 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#22','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C5',3,'error','auto','로봇이 경주에서 7 cm씩 5칸 갔어요. 이동한 거리를 구하는 방법을 잘못 말한 사람은 누구인가요?',ARRAY['M2-2-u2-X03','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C5","difficulty":3,"kind":"error","stem":"로봇이 경주에서 7 cm씩 5칸 갔어요. 이동한 거리를 구하는 방법을 잘못 말한 사람은 누구인가요?","options":[{"t":"하린: 7 × 4 = 28이므로 28 cm야.","correct":true,"mis_target":"M2-2-u2-X03"},{"t":"도윤: 7씩 5번 더하면 구할 수 있어.","mis":"M2-2-u2-X15"},{"t":"세아: 7 × 3에 7 × 2를 더해서 구할 수 있어.","mis":"M2-2-u2-X15"}],"explanation":["이동한 거리는 7 × 5 = 35 cm예요.","하린이는 4칸만 세었어요.","그래서 하린이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#23','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',4,'essay','teacher','의자가 한 줄에 6개씩 4줄로 놓여 있는데 두 자리가 비어 있어요. 의자의 수를 두 가지 방법으로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"의자가 한 줄에 6개씩 4줄로 놓여 있는데 두 자리가 비어 있어요. 의자의 수를 두 가지 방법으로 구하고 설명해 보세요.","answer_guide":{"answer":"예) 빈자리까지 채우면 6 × 4 = 24개이고 2를 빼면 22개이다. 꽉 찬 3줄은 6 × 3 = 18개, 남은 줄의 4개를 더하면 22개이다.","scoring_points":["한 가지 방법(나누어 곱하고 더하기 등)으로 바르게 구했는가","다른 방법(채워 곱하고 빼기 등)으로도 구했는가","답을 바르게 썼는가"]},"explanation":["줄 맞춰 놓이지 않은 모양은 보조선을 그어 나누어요.","나눈 덩이마다 곱셈구구로 구해 더해요.","빈자리까지 채워 곱한 뒤 빼도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#24','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C10',4,'essay','teacher','3단과 7단 곱셈구구의 곱의 일의 자리 숫자를 0이 나올 때까지 차례로 쓰고, 0~9 활동판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"3단과 7단 곱셈구구의 곱의 일의 자리 숫자를 0이 나올 때까지 차례로 쓰고, 0~9 활동판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.","answer_guide":{"answer":"예) 3단: 3, 6, 9, 2, 5, 8, 1, 4, 7, 0 / 7단: 7, 4, 1, 8, 5, 2, 9, 6, 3, 0. 같은 숫자들을 순서만 거꾸로 이으므로 같은 무늬가 나온다.","scoring_points":["3단의 일의 자리 숫자를 바르게 썼는가","7단의 일의 자리 숫자를 바르게 썼는가","같은 숫자를 거꾸로 잇기 때문이라고 설명했는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","두 단의 숫자를 나란히 놓고 견주어 봐요.","같은 점들을 반대 방향으로 이으면 같은 무늬가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_c#25','math',2,2,'u2','','tb_g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 수 찾기 놀이를 해요. 36을 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 수 찾기 놀이를 해요. 36을 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.","answer_guide":{"answer":"예) 4단 곱셈구구에 있는 수야. 6 × 6의 곱이야. 7 × 5보다 1 커.","scoring_points":["36이 있는 단을 바르게 말했는가","곱셈식이나 크기 비교로 설명했는가","서로 다른 방법으로 세 가지를 말했는가"]},"explanation":["그 수가 곱셈표의 어느 칸에 있는지 찾아요.","어느 단에 있는지, 어떤 곱보다 큰지·작은지로 말할 수 있어요.","앞 친구와 다른 방법으로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#1','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',1,'mc','auto','4 × 8 = 32예요. 이것을 이용하여 4 × 9를 구하면 얼마인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X01']::text[],false,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"4 × 8 = 32예요. 이것을 이용하여 4 × 9를 구하면 얼마인가요?","options":[{"t":"36","correct":true},{"t":"41","mis":"M2-2-u2-X17"},{"t":"33","mis":"M2-2-u2-X01"}],"explanation":["4 × 9는 4 × 8보다 4만큼 더 커요.","32 + 4 = 36이에요.","한 번 더 더할 때는 곱하는 수 9가 아니라 그 단의 수 4를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#2','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C7',1,'mc','auto','4 × □ = 0 에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"4 × □ = 0 에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"4","mis":"M2-2-u2-X05"}],"explanation":["1과 어떤 수의 곱, 어떤 수와 1의 곱은 그 수예요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 0이에요.","4 × 0 = 0 — □는 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#3','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C5',1,'sa','auto','7 × 3 = □ 에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"7 × 3 = □ 에서 □ 안에 알맞은 수는 얼마인가요?","answer":["21"],"explanation":["7 × 3은 7을 3번 더한 것이에요.","7 × 3 = 21이에요.","곱하는 수가 1 커질 때마다 7씩 커지는 것으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#4','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C2',1,'mc','auto','쟁반 한 개에 딸기가 5개씩, 쟁반이 7개 있어요. 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":4,"concept":"M2-2-u2-C2","difficulty":1,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩, 쟁반이 7개 있어요. 딸기는 모두 몇 개인가요?","options":[{"t":"35개","correct":true},{"t":"12개","mis":"M2-2-u2-X06"},{"t":"40개","mis":"M2-2-u2-X02"}],"explanation":["5씩 7묶음이에요.","5 × 7 = 35예요.","두 수를 더하지 말고 5를 7번 더해요."],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#5','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C3',1,'mc','auto','장난감이 6개씩 6묶음 있어요. 장난감은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":5,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"장난감이 6개씩 6묶음 있어요. 장난감은 모두 몇 개인가요?","options":[{"t":"36개","correct":true},{"t":"12개","mis":"M2-2-u2-X06"},{"t":"30개","mis":"M2-2-u2-X02"}],"explanation":["6씩 6묶음이에요.","6 × 6 = 36이에요.","곱하는 수가 1 커질 때마다 6씩 커져요."],"asset":{"type":"mul_groups","item":"🧸","k":6,"n":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#6','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C5',1,'sa','auto','로봇 경주에서 로봇이 한 칸에 7 cm씩 3칸 이동했어요. 이동한 거리는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"로봇 경주에서 로봇이 한 칸에 7 cm씩 3칸 이동했어요. 이동한 거리는 몇 cm인가요?","answer":["21","21 cm"],"explanation":["7씩 3묶음이에요.","7 × 3 = 21이에요.","이동한 거리는 21 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#7','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',1,'mc','auto','야구공이 한 상자에 9개씩 들어 있어요. 상자 7개에 들어 있는 야구공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"야구공이 한 상자에 9개씩 들어 있어요. 상자 7개에 들어 있는 야구공은 모두 몇 개인가요?","options":[{"t":"63개","correct":true},{"t":"16개","mis":"M2-2-u2-X06"},{"t":"54개","mis":"M2-2-u2-X02"}],"explanation":["9씩 7묶음이에요.","9 × 7 = 63이에요.","상자가 하나 늘 때마다 야구공은 9개씩 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#8','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","options":[{"t":"36","correct":true},{"t":"32","mis":"M2-2-u2-X09"},{"t":"45","mis":"M2-2-u2-X09"}],"explanation":["세로줄의 4와 가로줄의 9가 만나는 칸이에요.","4 × 9 = 36이에요.","이웃 칸의 수와 헷갈리지 않게 두 손가락으로 짚어요."],"asset":{"type":"gugu_table","rows":[3,4,5],"cols":[7,8,9],"q":[4,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#9','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 9단 곱셈구구의 곱은 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],false,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 9단 곱셈구구의 곱은 얼마씩 커지나요?","options":[{"t":"9","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"18","mis":"M2-2-u2-X02"}],"explanation":["9단의 곱은 9, 18, 27, …예요.","오른쪽으로 한 칸 갈 때마다 9씩 커져요.","곱하는 수가 1 커지면 곱은 그 단의 수만큼 커져요."],"asset":{"type":"gugu_table","rows":[7,8,9],"cols":[1,2,3,4,5,6,7,8,9],"hrow":9}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#10','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',2,'mc','auto','연결 모형이 6개씩 2줄과 3개씩 5줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18']::text[],false,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"연결 모형이 6개씩 2줄과 3개씩 5줄로 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"27개","correct":true},{"t":"15개","mis":"M2-2-u2-X18"},{"t":"12개","mis":"M2-2-u2-X18"}],"explanation":["6 × 2 = 12예요.","3 × 5 = 15예요.","두 덩이를 더하면 12 + 15 = 27이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#11','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',2,'ox','auto','8 × 7은 4 × 7을 두 번 더한 것과 같아요.',ARRAY['M2-2-u2-X17']::text[],false,'{"seq":11,"concept":"M2-2-u2-C4","difficulty":2,"kind":"ox","stem":"8 × 7은 4 × 7을 두 번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"8씩 한 묶음은 4씩 두 묶음이라 28 + 28 = 56이니까","correct":true},{"t":"4 × 7에 4를 더하면 8 × 7이 되니까","mis":"M2-2-u2-X17"}],"mis":"M2-2-u2-X17","explanation":["4 × 7 = 28이에요.","28 + 28 = 56 = 8 × 7이에요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#12','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',2,'mc','auto','9 × 4를 나타낸 그림을 4개씩 묶어 보면 4의 몇 배와 같나요?',ARRAY['M2-2-u2-X07','M2-2-u2-X05']::text[],false,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × 4를 나타낸 그림을 4개씩 묶어 보면 4의 몇 배와 같나요?","options":[{"t":"9배","correct":true},{"t":"4배","mis":"M2-2-u2-X07"},{"t":"36배","mis":"M2-2-u2-X05"}],"explanation":["9씩 4묶음을 4개씩 다시 묶어요.","4개씩 9묶음 — 4의 9배예요.","그래서 9 × 4 = 4 × 9 = 36이에요."],"asset":{"type":"mul_groups","item":"⭐","k":9,"n":4,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#13','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C7',2,'mc','auto','재이가 0, 1, 2, 3이 적힌 공을 꺼낸 횟수는 1번, 3번, 0번, 3번이에요. 재이가 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X08']::text[],false,'{"seq":13,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"재이가 0, 1, 2, 3이 적힌 공을 꺼낸 횟수는 1번, 3번, 0번, 3번이에요. 재이가 얻은 점수는 모두 몇 점인가요?","options":[{"t":"12점","correct":true},{"t":"7점","mis":"M2-2-u2-X05"},{"t":"13점","mis":"M2-2-u2-X08"}],"explanation":["0 × 1 = 0, 1 × 3 = 3, 2 × 0 = 0, 3 × 3 = 9예요.","0 + 3 + 0 + 9 = 12예요.","0점 칸이나 한 번도 못 얻은 점수는 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#14','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 5 × 8과 곱이 같은 곱셈구구는 어느 것인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":14,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 5 × 8과 곱이 같은 곱셈구구는 어느 것인가요?","options":[{"t":"8 × 5","correct":true},{"t":"5 × 9","mis":"M2-2-u2-X09"},{"t":"8 × 8","mis":"M2-2-u2-X09"}],"explanation":["5 × 8 = 40이에요.","8 × 5 = 40이에요.","두 수를 바꾸어 곱해도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#15','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',2,'sa','auto','8씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":15,"concept":"M2-2-u2-C4","difficulty":2,"kind":"sa","stem":"8씩 뛰어 센 수직선이에요. 빈칸에 알맞은 수는 얼마인가요?","answer":["40"],"explanation":["8씩 커지는 수예요.","빈칸은 8 × 5 = 40이에요.","4씩 두 번 뛰면 8씩 한 번 뛴 것과 같아요."],"asset":{"type":"jump_row","cells":[24,32,null,48],"step":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#16','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',2,'mc','auto','9단의 곱은 십의 자리 숫자가 곱하는 수보다 1 작고, 두 숫자의 합이 9예요. 9 × 4의 곱은 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":16,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9단의 곱은 십의 자리 숫자가 곱하는 수보다 1 작고, 두 숫자의 합이 9예요. 9 × 4의 곱은 얼마인가요?","options":[{"t":"36","correct":true},{"t":"63","mis":"M2-2-u2-X16"},{"t":"46","mis":"M2-2-u2-X16"}],"explanation":["십의 자리 숫자는 4보다 1 작은 3이에요.","3 + 6 = 9이니 일의 자리 숫자는 6이에요.","그래서 9 × 4 = 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#17','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',3,'mc','auto','어떤 수인지 구해 보세요. ① 3단 곱셈구구에 있는 수예요. ② 홀수예요. ③ 4 × 5보다 크고 5 × 5보다 작아요.',ARRAY['M2-2-u2-X20']::text[],false,'{"seq":17,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"어떤 수인지 구해 보세요. ① 3단 곱셈구구에 있는 수예요. ② 홀수예요. ③ 4 × 5보다 크고 5 × 5보다 작아요.","options":[{"t":"21","correct":true},{"t":"24","mis":"M2-2-u2-X20"},{"t":"27","mis":"M2-2-u2-X20"}],"explanation":["20보다 크고 25보다 작은 3단의 수는 21, 24예요.","그중 홀수는 21이에요.","24는 짝수, 27은 범위 밖이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#18','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',3,'mc','auto','의자가 한 줄에 7개씩 3줄로 놓여 있는데 한 자리가 비어 있어요. 의자는 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X03']::text[],false,'{"seq":18,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"의자가 한 줄에 7개씩 3줄로 놓여 있는데 한 자리가 비어 있어요. 의자는 모두 몇 개인가요?","options":[{"t":"20개","correct":true},{"t":"21개","mis":"M2-2-u2-X18"},{"t":"14개","mis":"M2-2-u2-X03"}],"explanation":["빈자리까지 채우면 7 × 3 = 21개예요.","빈자리 1개를 빼요.","21 − 1 = 20이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#19','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',3,'mc','auto','가위바위보를 하여 이기면 7점을 얻는 놀이를 6번 했어요. 재이는 4번 이겼어요. 재이가 얻은 점수는 몇 점인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X06']::text[],false,'{"seq":19,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"가위바위보를 하여 이기면 7점을 얻는 놀이를 6번 했어요. 재이는 4번 이겼어요. 재이가 얻은 점수는 몇 점인가요?","options":[{"t":"28점","correct":true},{"t":"42점","mis":"M2-2-u2-X05"},{"t":"11점","mis":"M2-2-u2-X06"}],"explanation":["한 번 이길 때 7점, 4번 이겼어요.","7 × 4 = 28이에요.","놀이한 횟수 6번 모두 이긴 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#20','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C10',3,'mc','auto','곱셈구구 속 비밀을 찾아요. 8단 곱셈구구의 곱의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":20,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"곱셈구구 속 비밀을 찾아요. 8단 곱셈구구의 곱의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"8, 6, 4, 2, 0, 8, 6, 4, 2","correct":true},{"t":"8, 16, 24, 32, 40, 48, 56, 64, 72","mis":"M2-2-u2-X16"},{"t":"1, 2, 3, 4, 5, 6, 7, 8, 9","mis":"M2-2-u2-X16"}],"explanation":["8단의 곱은 8, 16, 24, 32, 40, 48, 56, 64, 72예요.","일의 자리 숫자만 쓰면 8, 6, 4, 2, 0, 8, 6, 4, 2예요.","이 숫자를 0~9 활동판에 차례로 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#21','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',3,'mc','auto','곱셈표에서 2 × 8과 곱이 같은 곱셈구구를 빠짐없이 모두 고른 것은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":21,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표에서 2 × 8과 곱이 같은 곱셈구구를 빠짐없이 모두 고른 것은 어느 것인가요?","options":[{"t":"8 × 2, 4 × 4","correct":true},{"t":"8 × 2","mis":"M2-2-u2-X13"},{"t":"4 × 4","mis":"M2-2-u2-X13"}],"explanation":["2 × 8 = 16이에요.","곱셈표에서 16이 있는 칸을 모두 찾으면 8 × 2, 4 × 4예요.","두 수를 바꾼 것과 다른 단의 것까지 모두 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#22','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C5',3,'error','auto','사탕이 한 묶음에 7개씩 4묶음 있어요. 사탕의 수를 구하는 방법을 잘못 말한 사람은 누구인가요?',ARRAY['M2-2-u2-X03','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C5","difficulty":3,"kind":"error","stem":"사탕이 한 묶음에 7개씩 4묶음 있어요. 사탕의 수를 구하는 방법을 잘못 말한 사람은 누구인가요?","options":[{"t":"라온: 7 × 3 = 21이므로 모두 21개야.","correct":true,"mis_target":"M2-2-u2-X03"},{"t":"나은: 7씩 4번 더하면 구할 수 있어.","mis":"M2-2-u2-X15"},{"t":"세미: 4개씩 7줄로 생각해 4 × 7로 구할 수 있어.","mis":"M2-2-u2-X15"}],"explanation":["사탕은 7 × 4 = 28개예요.","라온이는 3묶음만 세었어요.","그래서 라온이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#23','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',4,'essay','teacher','연결 모형이 3개씩 2줄과 4개씩 3줄로 붙어 있어요. 연결 모형의 수를 두 가지 방법으로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"연결 모형이 3개씩 2줄과 4개씩 3줄로 붙어 있어요. 연결 모형의 수를 두 가지 방법으로 구하고 설명해 보세요.","answer_guide":{"answer":"예) 3 × 2 = 6과 4 × 3 = 12를 더하면 18개이다. 3개씩 2줄은 2개씩 3줄로도 볼 수 있어 2 × 3 = 6, 4 × 3 = 12를 더해도 18개이다.","scoring_points":["한 가지 방법(나누어 곱하고 더하기 등)으로 바르게 구했는가","다른 방법(채워 곱하고 빼기 등)으로도 구했는가","답을 바르게 썼는가"]},"explanation":["줄 맞춰 놓이지 않은 모양은 보조선을 그어 나누어요.","나눈 덩이마다 곱셈구구로 구해 더해요.","빈자리까지 채워 곱한 뒤 빼도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#24','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C10',4,'essay','teacher','1단과 9단 곱셈구구의 곱의 일의 자리 숫자를 0이 나올 때까지 차례로 쓰고, 0~9 활동판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"1단과 9단 곱셈구구의 곱의 일의 자리 숫자를 0이 나올 때까지 차례로 쓰고, 0~9 활동판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.","answer_guide":{"answer":"예) 1단: 1, 2, 3, 4, 5, 6, 7, 8, 9, 0 / 9단: 9, 8, 7, 6, 5, 4, 3, 2, 1, 0. 같은 숫자들을 순서만 거꾸로 이으므로 같은 무늬가 나온다.","scoring_points":["1단의 일의 자리 숫자를 바르게 썼는가","9단의 일의 자리 숫자를 바르게 썼는가","같은 숫자를 거꾸로 잇기 때문이라고 설명했는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","두 단의 숫자를 나란히 놓고 견주어 봐요.","같은 점들을 반대 방향으로 이으면 같은 무늬가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u2_review_d#25','math',2,2,'u2','','tb_g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 수 찾기 놀이를 해요. 12를 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 수 찾기 놀이를 해요. 12를 친구가 찾을 수 있도록 곱셈구구를 써서 서로 다른 방법으로 세 가지 설명해 보세요.","answer_guide":{"answer":"예) 2단에도 3단에도 있는 수야. 4 × 3의 곱이야. 2 × 5보다 2 커.","scoring_points":["12가 있는 단을 바르게 말했는가","곱셈식이나 크기 비교로 설명했는가","서로 다른 방법으로 세 가지를 말했는가"]},"explanation":["그 수가 곱셈표의 어느 칸에 있는지 찾아요.","어느 단에 있는지, 어떤 곱보다 큰지·작은지로 말할 수 있어요.","앞 친구와 다른 방법으로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
